INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0545', 'Kettlebell Plyo Push-Up', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'kettlebell', 'strength', NULL, '["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.","Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.","Repeat for the desired number of repetitions."]', '["अपने हाथों को केटलबेल्स पर कंधे की चौड़ाई की दूरी पर रखते हुए ऊंची तख़्त स्थिति में शुरुआत करें।","अपनी कोहनियों को अपने शरीर के पास रखते हुए, अपनी छाती को ज़मीन की ओर झुकाएँ।","अपने हाथों को विस्फोटक तरीके से दबाएं, अपने हाथों को केटलबेल से उठाएं और अपनी बाहों को पूरी तरह फैलाएं।","धीरे से केटलबेल्स पर वापस आएँ और अगली पुनरावृत्ति के लिए तुरंत अपनी छाती को वापस नीचे कर लें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0546', 'Kettlebell Seated Press', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder height, palms facing forward.","Press the kettlebells overhead, fully extending your arms.","Lower the kettlebells back to shoulder height.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें, हथेलियाँ आगे की ओर हों।","अपनी बाहों को पूरी तरह फैलाते हुए केटलबेल्स को ऊपर की ओर दबाएं।","केटलबेल्स को वापस कंधे की ऊँचाई तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Kettlebell_Seated_Press/0.jpg","Kettlebell_Seated_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1438', 'Kettlebell Seated Two Arm Military Press', 'shoulders', 'delts', '["triceps","upper back"]', 'kettlebell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder level with your palms facing forward.","Press the kettlebells overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में कंधे के स्तर पर केटलबेल पकड़ें।","अपनी भुजाओं को पूरा फैलाकर केटलबेल्स को ऊपर की ओर दबाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल्स को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0547', 'Kettlebell Seesaw Press', 'shoulders', 'delts', '["triceps","core"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead while keeping the other kettlebell at shoulder height.","Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.","Continue alternating the pressing motion, creating a seesaw-like movement.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर केटलबेल पकड़ें।","एक केटलबेल को ऊपर की ओर दबाएं जबकि दूसरे केटलबेल को कंधे की ऊंचाई पर रखें।","दबाए गए केटलबेल को वापस कंधे की ऊंचाई तक कम करें, साथ ही दूसरे केटलबेल को ऊपर की ओर दबाएं।","झूले जैसी गति बनाते हुए, दबाने की गति को बारी-बारी से जारी रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Kettlebell_Seesaw_Press/0.jpg","Kettlebell_Seesaw_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0548', 'Kettlebell Sumo High Pull', 'back', 'traps', '["shoulders","glutes","hamstrings"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Hold a kettlebell with both hands in front of your body, arms extended downwards.","Bend your knees and lower your hips into a squat position, keeping your back straight.","Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.","As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां बाहर की ओर हों।","अपने शरीर के सामने दोनों हाथों से केटलबेल को पकड़ें, बाहें नीचे की ओर फैली हुई हों।","अपने घुटनों को मोड़ें और अपनी पीठ को सीधा रखते हुए अपने कूल्हों को स्क्वाट स्थिति में लाएँ।","अपनी एड़ी के माध्यम से ड्राइव करें और अपने कूल्हों और घुटनों को विस्फोटक रूप से फैलाएं, केटलबेल को अपनी ठोड़ी की ओर खींचें।","जैसे ही आप केटलबेल को ऊपर खींचते हैं, अपनी कोहनियों को ऊंचा और चौड़ा रखें, और अपने कंधे के ब्लेड को एक साथ दबाएं।","केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', '["Kettlebell_Sumo_High_Pull/0.jpg","Kettlebell_Sumo_High_Pull/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0549', 'Kettlebell Swing', 'upper legs', 'glutes', '["hamstrings","core"]', 'kettlebell', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointed slightly outward.","Hold the kettlebell with both hands in front of your body, arms extended.","Bend your knees slightly and hinge at the hips, pushing your butt back.","Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.","Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.","Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपने शरीर के सामने दोनों हाथों से केटलबेल को पकड़ें, बाहें फैली हुई।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर टिकाएं, अपने बट को पीछे धकेलें।","अपनी बाहों को सीधा रखते हुए और अपनी पीठ को सपाट रखते हुए, केटलबेल को अपने पैरों के बीच वापस घुमाएँ।","अपने कूल्हों को आगे बढ़ाएं और अपने कूल्हों द्वारा उत्पन्न गति का उपयोग करते हुए केटलबेल को कंधे की ऊंचाई तक घुमाएं।","केटलबेल को अपने पैरों के बीच वापस झूलने दें और वांछित संख्या में दोहराव के लिए इस क्रिया को दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0550', 'Kettlebell Thruster', 'shoulders', 'delts', '["quadriceps","glutes","core"]', 'kettlebell', 'strength', 'intermediate', '["Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.","Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.","Lock out your arms at the top of the movement, fully extending your elbows.","Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े होकर शुरुआत करें, दोनों हाथों से अपनी छाती के सामने केटलबेल पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए, अपनी छाती को ऊपर और अपनी पीठ को सीधा रखते हुए स्क्वाट स्थिति में आ जाएँ।","जैसे ही आप स्क्वाट के निचले भाग तक पहुँचते हैं, खड़े होने के लिए अपनी एड़ी के माध्यम से विस्फोटक रूप से ड्राइव करें, साथ ही केटलबेल को ऊपर की ओर दबाएँ।","अपनी कोहनियों को पूरी तरह फैलाते हुए, अपनी भुजाओं को गति के शीर्ष पर लॉक कर लें।","गति को उलट कर, अपनी कोहनियों को मोड़कर और वजन को वापस अपनी छाती पर लाकर केटलबेल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Kettlebell_Thruster/0.jpg","Kettlebell_Thruster/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0551', 'Kettlebell Turkish Get Up (Squat Style)', 'upper legs', 'glutes', '["quadriceps","hamstrings","core"]', 'kettlebell', 'strength', 'intermediate', '["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.","Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Pressing through your right foot, lift your hips off the ground, coming into a bridge position.","Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.","Rotate your torso to the left, bringing your left hand to the ground for support.","Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.","From the kneeling position, stand up, keeping the kettlebell extended overhead.","Reverse the movement to return to the starting position.","Repeat the exercise on the other side, starting with the kettlebell in your left hand."]', '["अपने पैरों को फैलाकर अपनी पीठ के बल लेटकर शुरुआत करें और केटलबेल को अपने दाहिने हाथ में पकड़ें, हाथ पूरी तरह से आपके कंधे के ऊपर फैला हुआ हो।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने पैर को जमीन पर सपाट रखें, अपने बाएं पैर को फैलाए रखें।","अपने दाहिने पैर से दबाव डालते हुए, पुल की स्थिति में आते हुए, अपने कूल्हों को ज़मीन से ऊपर उठाएं।","अपने बाएँ पैर को अपने शरीर के नीचे सरकाएँ, अपने बाएँ घुटने को मोड़ें और अपने बाएँ पैर को ज़मीन पर सपाट रखें।","अपने धड़ को बाईं ओर घुमाएं, समर्थन के लिए अपने बाएं हाथ को जमीन पर लाएं।","अपने दाहिने पैर और बाएं हाथ से दबाव डालते हुए, घुटने टेकने की स्थिति में आते हुए, अपने धड़ को जमीन से ऊपर उठाएं।","घुटनों के बल बैठने की स्थिति से, केटलबेल को सिर के ऊपर रखते हुए खड़े हो जाएं।","प्रारंभिक स्थिति में लौटने के लिए आंदोलन को उल्टा करें।","अपने बाएं हाथ में केटलबेल से शुरुआत करते हुए व्यायाम को दूसरी तरफ से दोहराएं।"]', '["Kettlebell_Turkish_Get-Up_Squat_style/0.jpg","Kettlebell_Turkish_Get-Up_Squat_style/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0552', 'Kettlebell Two Arm Clean', 'shoulders', 'delts', '["traps","forearms"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से अपनी जांघों के सामने केटलबेल पकड़ें, हथेलियाँ आपकी ओर हों।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर टिकाएं, केटलबेल को ज़मीन की ओर नीचे करें।","केटलबेल को अपने कंधों की ओर खींचने के लिए गति का उपयोग करते हुए, अपने कूल्हों और घुटनों को तेजी से फैलाएं।","जैसे ही केटलबेल कंधे की ऊंचाई तक पहुंचती है, अपनी कलाइयों को घुमाएं और केटलबेल को रैक स्थिति में पकड़ें, अपनी कोहनियों को अंदर की ओर रखते हुए और केटलबेल को अपनी बांह के पिछले हिस्से पर टिकाते हुए।","केटलबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', '["Two-Arm_Kettlebell_Clean/0.jpg","Two-Arm_Kettlebell_Clean/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0553', 'Kettlebell Two Arm Military Press', 'shoulders', 'delts', '["triceps","upper back"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Engage your core and press the kettlebells overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में कंधे के स्तर पर केटलबेल पकड़ें।","अपने कोर को संलग्न करें और अपनी बाहों को पूरी तरह फैलाते हुए केटलबेल्स को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल्स को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Two-Arm_Kettlebell_Military_Press/0.jpg","Two-Arm_Kettlebell_Military_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1345', 'Kettlebell Two Arm Row', 'back', 'upper back', '["biceps","forearms"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में एक केटलबेल पकड़ें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कूल्हों के बल आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, केटलबेल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केटलबेल्स को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Two-Arm_Kettlebell_Row/0.jpg","Two-Arm_Kettlebell_Row/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0554', 'Kettlebell Windmill', 'waist', 'abs', '["obliques","shoulders"]', 'kettlebell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.","Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.","Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.","Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.","Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने दाहिने हाथ में केटलबेल को सिर के ऊपर पकड़ लें।","अपने बाएँ पैर को लगभग 45 डिग्री तक बाहर की ओर घुमाएँ और अपने दाहिने पैर को आगे की ओर रखें।","अपने धड़ को बायीं ओर मोड़ें, अपने दाहिने हाथ को ऊपर की ओर फैलाकर रखें और अपनी आँखें केटलबेल पर रखें।","अपने दाहिने हाथ को सीधा रखते हुए और अपने बाएं हाथ को बगल की ओर फैलाते हुए अपने धड़ को जितना हो सके नीचे करें।","एक पल के लिए रुकें, फिर अपने दाहिने पैर से धक्का देकर और अपनी तिरछी उंगलियों को जोड़कर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', '["Kettlebell_Windmill/0.jpg","Kettlebell_Windmill/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0555', 'Kick Out Sit', 'upper legs', 'hamstrings', '["quadriceps","glutes"]', 'body weight', 'strength', NULL, '["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Lean back slightly and place your hands on the edge of the bench or chair for support.","Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक बेंच या कुर्सी के किनारे पर बैठें।","थोड़ा पीछे झुकें और सहारे के लिए अपने हाथों को बेंच या कुर्सी के किनारे पर रखें।","अपनी हैमस्ट्रिंग को जोड़ते हुए, अपने पैरों को ज़मीन से ऊपर उठाएं और अपने पैरों को सीधे अपने सामने फैलाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने घुटनों को मोड़ें और अपने पैरों को वापस अपने शरीर की ओर लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0558', 'Kipping Muscle Up', 'back', 'lats', '["biceps","triceps","shoulders","core"]', 'body weight', 'strength', NULL, '["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and use a swinging motion to generate momentum.","As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.","Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Lower yourself back down to the starting position by bending your arms and controlling the descent.","Repeat for the desired number of repetitions."]', '["ओवरहैंड पकड़ के साथ पुल-अप बार से लटकने से शुरुआत करें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने मूल को संलग्न करें और गति उत्पन्न करने के लिए एक झूलती गति का उपयोग करें।","जैसे ही आप आगे की ओर झूलते हैं, आंदोलन शुरू करने के लिए अपने लैट्स और बाइसेप्स का उपयोग करते हुए अपनी छाती को बार की ओर खींचें।","जब तक आपकी छाती बार तक नहीं पहुंच जाती, तब तक ऊपर की ओर गति जारी रखें, फिर बार को नीचे की ओर धकेलते हुए और अपनी बाहों को फैलाकर डिप स्थिति में आ जाएं।","अपनी भुजाओं को मोड़कर और ढलान को नियंत्रित करके अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3640', 'Knee Touch Crunch', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने एब्स को शामिल करते हुए, अपने कंधे के ब्लेड को जमीन से ऊपर उठाएं और अपने दाहिने हाथ को अपने बाएं घुटने की ओर ले जाएं।","प्रारंभिक स्थिति पर लौटें और दोहराएं, इस बार अपने बाएं हाथ को अपने दाहिने घुटने तक ले जाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1420', 'Kneeling Jump Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', 'expert', '["Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.","Hold a barbell across your upper back, resting it on your shoulders.","Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.","As you jump, push through your toes and fully extend your ankles, knees, and hips.","Land softly back on the ground, bending your knees to absorb the impact.","Immediately go into the next repetition, repeating the jump squat motion."]', '["अपने पैरों को कूल्हे-चौड़ाई पर अलग रखते हुए और अपने पैर की उंगलियों को आगे की ओर रखते हुए जमीन पर घुटने टेककर शुरुआत करें।","अपनी ऊपरी पीठ पर एक बारबेल पकड़ें, इसे अपने कंधों पर टिकाएं।","अपने कोर और ग्लूट्स को संलग्न करें, फिर अपने कूल्हों और घुटनों को फैलाते हुए तेजी से हवा में उछलें।","जैसे ही आप कूदते हैं, अपने पैर की उंगलियों से धक्का दें और अपनी टखनों, घुटनों और कूल्हों को पूरी तरह फैलाएँ।","प्रभाव को अवशोषित करने के लिए अपने घुटनों को मोड़ते हुए, धीरे से वापस जमीन पर उतरें।","जंप स्क्वाट गति को दोहराते हुए तुरंत अगली पुनरावृत्ति पर जाएं।"]', '["Kneeling_Jump_Squat/0.jpg","Kneeling_Jump_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1346', 'Kneeling Lat Stretch', 'back', 'lats', '["shoulders","triceps"]', 'body weight', 'strength', NULL, '["Kneel on the ground with your knees hip-width apart and your toes pointing back.","Extend your arms overhead and interlace your fingers.","Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को कूल्हे-चौड़ाई पर अलग रखते हुए और अपने पैर की उंगलियों को पीछे की ओर रखते हुए जमीन पर झुकें।","अपनी बाहों को ऊपर की ओर फैलाएं और अपनी उंगलियों को आपस में फंसा लें।","अपनी पीठ को सीधा रखते हुए, धीरे-धीरे दाहिनी ओर झुकें, अपनी बाईं लैट मांसपेशी में खिंचाव महसूस करें।","20-30 सेकंड तक खिंचाव बनाए रखें, फिर प्रारंभिक स्थिति में लौट आएं।","बाईं ओर के खिंचाव को दोहराएं, बाईं ओर झुकें और अपनी दाहिनी लैट मांसपेशी में खिंचाव महसूस करें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3239', 'Kneeling Plank Tap Shoulder (Male)', 'waist', 'abs', '["shoulders","triceps"]', 'body weight', 'strength', NULL, '["Start in a kneeling position with your hands on the ground, shoulder-width apart.","Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Return the hand to the ground and repeat with the other hand.","Continue alternating sides for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई के बराबर दूरी पर ज़मीन पर रखते हुए घुटनों के बल बैठ कर शुरुआत करें।","अपने पैरों को अपने पीछे फैलाएं, अपने पैर की उंगलियों पर आराम करें और अपने शरीर को तख़्त स्थिति में उठाएं।","अपने कोर को व्यस्त रखते हुए और अपने कूल्हों को स्थिर रखते हुए, एक हाथ को जमीन से ऊपर उठाएं और विपरीत कंधे को थपथपाएं।","हाथ को ज़मीन पर लौटाएँ और दूसरे हाथ से दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3211', 'Kneeling Push-Up (Male)', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई पर फैलाकर, उंगलियों को आगे की ओर रखते हुए, ज़मीन पर घुटने टेककर शुरुआत करें।","अपने पैरों को अपने पैरों के पंजों पर टिकाते हुए अपने पीछे फैलाएँ, ताकि आपका शरीर सिर से एड़ी तक एक सीधी रेखा बना ले।","अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","जब तक आपकी छाती जमीन से ठीक ऊपर न हो जाए, तब तक नीचे आना जारी रखें, फिर अपनी बाहों को सीधा करके प्रारंभिक स्थिति में वापस आ जाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3288', 'Korean Dips', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Position yourself between two parallel bars with your arms extended and supporting your body weight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को फैलाकर और अपने शरीर के वजन को सहारा देते हुए अपने आप को दो समानांतर पट्टियों के बीच रखें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ ज़मीन के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3418', 'L-Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["पुल-अप बार को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके लटकें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, अपने शरीर को बार की ओर खींचने के लिए अपने लैट्स और बाइसेप्स को संलग्न करें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3419', 'L-Sit On Floor', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Sit on the floor with your legs extended in front of you.","Place your hands on the floor beside your hips, fingers pointing forward.","Engage your core and lift your legs off the ground, keeping them straight.","Try to bring your legs parallel to the floor, forming an ''L'' shape with your body.","Hold this position for as long as you can.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को अपने सामने फैलाकर फर्श पर बैठें।","अपने हाथों को अपने कूल्हों के पास फर्श पर रखें, उंगलियां आगे की ओर हों।","अपने कोर को संलग्न करें और अपने पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं।","अपने शरीर के साथ ''L'' आकार बनाते हुए अपने पैरों को फर्श के समानांतर लाने का प्रयास करें।","जब तक आप कर सकते हैं इस स्थिति में रहें।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0562', 'Landmine 180', 'waist', 'abs', '["obliques","quadriceps"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.","Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.","As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.","Continue this twisting motion, alternating sides, for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से बारबेल को अपनी छाती के सामने पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपने धड़ को दाईं ओर घुमाएं, बारबेल को अपने दाहिने कूल्हे की ओर झुकाएं।","जैसे ही आप आंदोलन के निचले भाग पर पहुंचते हैं, गति को तुरंत उलट दें और अपने धड़ को बाईं ओर घुमाएं, बारबेल को ऊपर और अपने शरीर के पार अपने बाएं कंधे की ओर घुमाएं।","दोहराव की वांछित संख्या के लिए, पक्षों को बदलते हुए, इस घुमाव गति को जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3237', 'Landmine Lateral Raise', 'shoulders', 'delts', '["traps","upper back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, resting it on the front of your shoulders.","Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, इसे अपने कंधों के सामने रखें।","अपने कोर को व्यस्त रखते हुए और पीठ को सीधा रखते हुए, बारबेल को अपने शरीर से ऊपर और दूर उठाएं, इसे कंधे की ऊंचाई तक उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3300', 'Lean Planche', 'waist', 'abs', '["shoulders","chest","triceps"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands shoulder-width apart and your body straight.","Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Keep your elbows slightly bent and your body straight as you lean forward.","Hold this position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई पर अलग रखते हुए और अपने शरीर को सीधा रखते हुए पुश-अप स्थिति से शुरुआत करें।","अपने कोर को संलग्न करें और धीरे-धीरे अपना वजन आगे बढ़ाएं, अपने कंधों को अपने हाथों से आगे लाएं।","आगे की ओर झुकते समय अपनी कोहनियाँ थोड़ी मुड़ी हुई और शरीर सीधा रखें।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-2271', 'Left Hook. Boxing', 'shoulders', 'delts', '["biceps","triceps","forearms"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Keep your left hand up to protect your face and your right hand by your chin.","Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.","Twist your torso and engage your core muscles to generate power in the punch.","Snap your arm back to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपने चेहरे की सुरक्षा के लिए अपने बाएँ हाथ को ऊपर रखें और अपने दाहिने हाथ को अपनी ठुड्डी के पास रखें।","अपने कूल्हों को घुमाएँ और अपने बाएँ पैर को मोड़ें क्योंकि आप अपने बाएँ हाथ को मुक्का मारने की गति में आगे बढ़ाते हैं।","अपने धड़ को मोड़ें और मुक्के में शक्ति उत्पन्न करने के लिए अपनी मुख्य मांसपेशियों को शामिल करें।","अपने हाथ को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0570', 'Leg Pull In Flat Bench', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', 'beginner', '["Sit on a flat bench with your legs extended straight out in front of you.","Place your hands on the bench beside your hips for support.","Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को अपने सामने सीधा फैलाकर एक सपाट बेंच पर बैठें।","समर्थन के लिए अपने हाथों को अपने कूल्हों के पास बेंच पर रखें।","अपने पेट को संलग्न करें और अपने पैरों को जमीन से ऊपर उठाएं, अपने घुटनों को अपनी छाती की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Flat_Bench_Leg_Pull-In/0.jpg","Flat_Bench_Leg_Pull-In/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1576', 'Leg Up Hamstring Stretch', 'upper legs', 'hamstrings', '["glutes"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your legs extended.","Bend one knee and bring it towards your chest, holding onto your thigh or shin.","Straighten your leg as much as possible while keeping it elevated.","Hold the stretch for 20-30 seconds.","Repeat with the other leg."]', '["अपने पैरों को फैलाकर अपनी पीठ के बल सीधे लेट जाएँ।","एक घुटने को मोड़ें और अपनी जांघ या पिंडली को पकड़ते हुए इसे अपनी छाती की ओर लाएँ।","अपने पैर को ऊंचा रखते हुए जितना संभव हो उतना सीधा करें।","20-30 सेकंड तक खिंचाव बनाए रखें।","दूसरे पैर से दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2287', 'Lever Alternate Leg Press', 'upper legs', 'quads', '["hamstrings","glutes"]', 'leverage machine', 'strength', NULL, '["Adjust the seat and foot platform of the leverage machine to your desired position.","Sit on the machine with your back against the backrest and your feet on the foot platform.","Place your hands on the handles or sides of the machine for stability.","Push one foot against the foot platform, extending your leg until it is almost fully straight.","Pause for a moment, then slowly bend your leg and return to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["लीवरेज मशीन की सीट और फुट प्लेटफॉर्म को अपनी इच्छित स्थिति में समायोजित करें।","मशीन पर अपनी पीठ बैकरेस्ट से सटाकर और अपने पैरों को फुट प्लेटफॉर्म पर रखकर बैठें।","स्थिरता के लिए अपने हाथों को मशीन के हैंडल या किनारों पर रखें।","एक पैर को पैर के प्लेटफॉर्म पर दबाएं, अपने पैर को तब तक फैलाएं जब तक वह लगभग पूरी तरह से सीधा न हो जाए।","एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैर को मोड़ें और प्रारंभिक स्थिति में लौट आएं।","दूसरे पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0571', 'Lever Alternating Narrow Grip Seated Row', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your back straight and feet flat on the footplate.","Grasp the handles with a narrow grip, palms facing each other.","Keep your chest up and shoulders back throughout the exercise.","Pull one handle towards your torso while keeping the other handle stationary.","Squeeze your shoulder blades together at the end of the movement.","Slowly return the handle to the starting position and repeat with the other side.","Continue alternating sides for the desired number of repetitions."]', '["उचित संरेखण सुनिश्चित करने के लिए सीट की ऊंचाई और फ़ुटप्लेट की स्थिति को समायोजित करें।","अपनी पीठ सीधी करके और पैरों को फ़ुटप्लेट पर सपाट करके मशीन पर बैठें।","हैंडल को पतली पकड़ से पकड़ें, हथेलियाँ एक दूसरे के सामने हों।","पूरे अभ्यास के दौरान अपनी छाती ऊपर और कंधे पीछे रखें।","एक हैंडल को अपने धड़ की ओर खींचें जबकि दूसरे हैंडल को स्थिर रखें।","आंदोलन के अंत में अपने कंधे के ब्लेड को एक साथ निचोड़ें।","धीरे-धीरे हैंडल को शुरुआती स्थिति में लौटाएं और दूसरी तरफ से दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0572', 'Lever Assisted Chin-Up', 'back', 'lats', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the leverage machine to your desired resistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your body straight.","Engage your back muscles and pull your body up towards the handles, leading with your chest.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन को अपने वांछित प्रतिरोध स्तर पर समायोजित करें।","फुट प्लेटफॉर्म पर खड़े हो जाएं और हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपने शरीर को सीधा रखते हुए, अपनी बाहों को पूरी तरह फैलाकर लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए हैंडल की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी हैंडल के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0573', 'Lever Back Extension', 'back', 'spine', '["glutes","hamstrings"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to fit your body size and range of motion.","Sit on the machine with your back against the pad and your feet secured.","Place your hands on the handles or grip bars.","Engage your core and slowly lean forward, allowing your back to round slightly.","Pause for a moment at the bottom position, feeling a stretch in your lower back.","Using your back muscles, slowly raise your torso back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने शरीर के आकार और गति की सीमा के अनुरूप मशीन को समायोजित करें।","मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को सुरक्षित करके बैठें।","अपने हाथों को हैंडल या ग्रिप बार पर रखें।","अपने कोर को संलग्न करें और धीरे-धीरे आगे की ओर झुकें, जिससे आपकी पीठ थोड़ी गोल हो जाए।","अपनी पीठ के निचले हिस्से में खिंचाव महसूस करते हुए निचली स्थिति में एक पल के लिए रुकें।","अपनी पीठ की मांसपेशियों का उपयोग करते हुए, धीरे-धीरे अपने धड़ को प्रारंभिक स्थिति में वापस उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0574', 'Lever Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी निचली छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3200', 'Lever Bent-Over Row With V-Bar', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself facing the machine.","Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और अपने आप को मशीन के सामने रखें।","अपनी पीठ को सीधा रखते हुए और अपने घुटनों को थोड़ा मोड़ते हुए, वी-बार को ओवरहैंड ग्रिप से पकड़ें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, वी-बार को अपने पेट की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे वजन को प्रारंभिक स्थिति में वापस छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0575', 'Lever Bicep Curl', 'upper arms', 'biceps', '["forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.","Exhale and curl the handles upward, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने रखते हुए खुद को मशीन पर रखें।","हैंडल को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और अपनी कोहनियों को अपनी भुजाओं के पास रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए हैंडल को ऊपर की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए हैंडल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2289', 'Lever Calf Press', 'lower legs', 'calves', '["hamstrings"]', 'leverage machine', 'strength', NULL, '["Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.","Place your toes on the lever pad, with your heels hanging off the edge.","Grasp the handles or side supports for stability.","Push the lever pad down by extending your ankles, contracting your calf muscles.","Pause for a moment at the bottom of the movement.","Slowly return to the starting position by allowing your heels to rise back up.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन की सीट को समायोजित करें ताकि आपके कंधे लीवर पैड के साथ संरेखित हों।","अपने पैर की उंगलियों को लीवर पैड पर रखें, जबकि आपकी एड़ी किनारे से लटकी हुई हो।","स्थिरता के लिए हैंडल या साइड सपोर्ट को पकड़ें।","अपनी पिंडली की मांसपेशियों को सिकोड़ते हुए, अपनी एड़ियों को फैलाकर लीवर पैड को नीचे दबाएं।","आंदोलन के निचले भाग पर एक पल के लिए रुकें।","अपनी एड़ियों को वापस ऊपर उठने देते हुए धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0577', 'Lever Chest Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने सपाट रखते हुए अपने आप को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी कोहनियों को 90 डिग्री के कोण पर रखें।","हैंडल को तब तक आगे की ओर धकेलें जब तक कि आपकी भुजाएं पूरी तरह से विस्तारित न हो जाएं, आंदोलन के दौरान सांस छोड़ें।","आंदोलन के अंत में कुछ देर रुकें, फिर धीरे-धीरे सांस लेते हुए प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0576', 'Lever Chest Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने सपाट रखते हुए अपने आप को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी कोहनियों को 90 डिग्री के कोण पर रखें।","हैंडल को तब तक आगे की ओर धकेलें जब तक कि आपकी भुजाएं पूरी तरह से विस्तारित न हो जाएं, आंदोलन के दौरान सांस छोड़ें।","आंदोलन के अंत में कुछ देर रुकें, फिर धीरे-धीरे सांस लेते हुए प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0578', 'Lever Deadlift', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and foot platform to your desired position.","Sit on the machine with your back against the pad and your feet flat on the foot platform.","Grasp the handles or the sides of the seat for stability.","Engage your glutes and hamstrings, and push through your heels to lift the weight up.","Keep your back straight and avoid rounding your shoulders.","Extend your hips fully at the top of the movement, squeezing your glutes.","Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई और पैर के प्लेटफार्म को अपनी इच्छित स्थिति में समायोजित करें।","मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को फ़ुट प्लेटफ़ॉर्म पर सपाट करके बैठें।","स्थिरता के लिए सीट के हैंडल या किनारों को पकड़ें।","अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें, और वजन को ऊपर उठाने के लिए अपनी एड़ियों से धक्का दें।","अपनी पीठ सीधी रखें और अपने कंधों को गोल करने से बचें।","अपने कूल्हों को आंदोलन के शीर्ष पर पूरी तरह फैलाएं, अपने ग्लूट्स को निचोड़ें।","अपने ग्लूट्स और हैमस्ट्रिंग पर तनाव बनाए रखते हुए नियंत्रित तरीके से वजन वापस कम करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1300', 'Lever Decline Chest Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Slowly lower the handles back towards your chest, keeping your elbows slightly bent.","Pause for a moment at the bottom, then push the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन की सीट की ऊंचाई और बैकरेस्ट को आरामदायक स्थिति में समायोजित करें।","मशीन पर अपनी पीठ को पीछे की ओर टिकाकर बैठें और आपके पैर फर्श पर सपाट हों।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएं तब तक हैंडल को अपने शरीर से आगे और दूर धकेलें।","अपनी कोहनियों को थोड़ा मोड़ते हुए धीरे-धीरे हैंडल को वापस अपनी छाती की ओर नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर हैंडल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1253', 'Lever Donkey Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'leverage machine', 'strength', NULL, '["Adjust the leverage machine to the appropriate height for your body.","Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Place your hands on the handles or the support bars for stability.","Engage your calves and lift your heels as high as possible, using the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन को अपने शरीर के लिए उचित ऊंचाई पर समायोजित करें।","अपने आप को मशीन के सामने रखें, अपने पैर की उंगलियों को पैर के प्लेटफॉर्म पर रखें और आपकी एड़ी किनारे से लटकी हुई हो।","स्थिरता के लिए अपने हाथों को हैंडल या सपोर्ट बार पर रखें।","अपने पिंडलियों को संलग्न करें और अपने पैरों की उंगलियों का उपयोग करते हुए अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0579', 'Lever Front Pulldown', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.","Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपने घुटनों को पैड के नीचे और पैरों को जमीन पर सपाट रखते हुए मशीन पर खुद को रखें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी छाती को ऊपर उठाकर और अपने कंधों को पीछे करके सीधे बैठें, अपनी पीठ के निचले हिस्से में हल्का सा आर्क बनाए रखें।","अपने लैट्स को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी छाती की ओर खींचें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0580', 'Lever Gripless Shrug', 'back', 'traps', '["shoulders","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with your palms facing inwards and your arms fully extended.","Keeping your back straight, exhale and elevate your shoulders as high as possible.","Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और स्वयं को लीवरेज मशीन पर रखें।","अपनी हथेलियों को अंदर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर हैंडल को पकड़ें।","अपनी पीठ सीधी रखते हुए सांस छोड़ें और अपने कंधों को जितना हो सके ऊपर उठाएं।","कुछ देर के लिए संकुचन को रोककर रखें, फिर सांस लें और धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1439', 'Lever Gripless Shrug v. 2', 'back', 'traps', '["shoulders","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles or bars with an overhand grip, keeping your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने रखते हुए खुद को मशीन पर रखें।","अपनी भुजाओं को सीधा रखते हुए हैंडल या बार को ओवरहैंड ग्रिप से पकड़ें।","अपनी पीठ को सीधा रखते हुए, अपने कंधों को अपने कानों की ओर जितना संभव हो उतना ऊपर उठाएं।","एक क्षण के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2288', 'Lever Gripper Hands', 'lower arms', 'forearms', '["biceps","triceps"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and grip the handles of the leverage machine.","Keep your back straight and your feet flat on the ground.","Exhale and squeeze the handles, contracting your forearms.","Hold the contraction for a second, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और लीवरेज मशीन के हैंडल को पकड़ें।","अपनी पीठ सीधी और पैर ज़मीन पर सपाट रखें।","साँस छोड़ें और अपने अग्रबाहुओं को सिकोड़ते हुए हैंडल को निचोड़ें।","एक सेकंड के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1615', 'Lever Hammer Grip Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the preacher pad, ensuring your chest is pressed against it.","Grasp the handles with a hammer grip (palms facing each other).","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और स्वयं को लीवरेज मशीन पर रखें।","अपनी ऊपरी भुजाओं को उपदेशक पैड पर रखें, यह सुनिश्चित करते हुए कि आपकी छाती इसके खिलाफ दबी हुई है।","हैंडल को हथौड़े की पकड़ से पकड़ें (हथेलियाँ एक दूसरे के सामने)।","अपनी ऊपरी बांहों को स्थिर रखते हुए सांस छोड़ें और हैंडल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0581', 'Lever High Row', 'back', 'upper back', '["biceps","rear deltoids"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and foot platform to a comfortable position.","Sit on the machine with your chest against the pad and your feet flat on the foot platform.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई और पैर के प्लेटफार्म को आरामदायक स्थिति में समायोजित करें।","मशीन पर अपनी छाती को पैड से सटाकर और पैरों को फुट प्लेटफॉर्म पर सपाट करके बैठें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपने शरीर की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2286', 'Lever Hip Extension v. 2', 'upper legs', 'glutes', '["hamstrings"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your feet on the footrests and grip the handles for stability.","Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपने शरीर के अनुरूप समायोजित करें और अपनी पीठ को पीछे की ओर टिकाकर उस पर बैठें।","स्थिरता के लिए अपने पैरों को फुटरेस्ट पर रखें और हैंडल को पकड़ें।","अपने ग्लूट्स और हैमस्ट्रिंग को संलग्न करें, फिर अपने कूल्हों को फैलाने के लिए फुटरेस्ट पर दबाव डालें और अपने पैरों को पीछे की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2611', 'Lever Horizontal One Leg Press', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'leverage machine', 'strength', NULL, '["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Place your hands on the handles or sides of the machine for stability.","Push the footplate away from your body by extending your leg, keeping your back against the backrest.","Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["मशीन की सीट को इस तरह समायोजित करें कि जब आपके पैर फ़ुटप्लेट पर हों तो आपके घुटने 90 डिग्री के कोण पर हों।","मशीन पर अपनी पीठ बैकरेस्ट से सटाकर बैठें और आपके पैर फ़ुटप्लेट पर कंधे की चौड़ाई से अलग हों।","स्थिरता के लिए अपने हाथों को मशीन के हैंडल या किनारों पर रखें।","अपने पैर को फैलाकर, अपनी पीठ को बैकरेस्ट के सामने रखकर फ़ुटप्लेट को अपने शरीर से दूर धकेलें।","पूरी तरह से विस्तारित स्थिति में एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैर को मोड़कर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1299', 'Lever Incline Chest Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'leverage machine', 'strength', NULL, '["Adjust the seat and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन की सीट और बैकरेस्ट को आरामदायक स्थिति में समायोजित करें।","मशीन पर अपनी पीठ को पीछे की ओर टिकाकर बैठें और आपके पैर फर्श पर सपाट हों।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएं तब तक हैंडल को अपने शरीर से आगे और दूर धकेलें।","एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कोहनियों को मोड़ें और हैंडल को वापस अपनी छाती की ओर नीचे करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1479', 'Lever Incline Chest Press v. 2', 'chest', 'pectorals', '["triceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and backrest angle on the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.","Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन पर सीट की ऊंचाई और बैकरेस्ट कोण को आरामदायक स्थिति में समायोजित करें।","मशीन पर अपनी पीठ को पीछे की ओर टिकाकर बैठें और आपके पैर फर्श पर सपाट हों।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएं, तब तक हैंडल को अपने शरीर से आगे और दूर धकेलें, लेकिन अपनी कोहनियों को लॉक किए बिना।","पूरी तरह विस्तारित स्थिति में एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कोहनियों को मोड़ें और हैंडल को वापस अपनी छाती की ओर नीचे करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0582', 'Lever Kneeling Leg Curl', 'upper legs', 'hamstrings', '["glutes"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to fit your body and select the desired weight.","Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position, fully extending your knees.","Repeat for the desired number of repetitions."]', '["अपने शरीर के अनुरूप मशीन को समायोजित करें और वांछित वजन का चयन करें।","मशीन पर नीचे की ओर मुंह करके घुटने टेकें, अपने घुटनों को पैड पर टिकाएं और अपने पैरों को फ़ुटपैड के नीचे सुरक्षित रखें।","स्थिरता के लिए मशीन के हैंडल या किनारों को पकड़ें।","अपने ऊपरी शरीर को स्थिर रखते हुए, सांस छोड़ें और अपने घुटनों को मोड़ते हुए अपने पैरों को अपने ग्लूट्स की ओर मोड़ें।","अपनी हैमस्ट्रिंग को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में लाएं, अपने घुटनों को पूरी तरह से फैलाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0583', 'Lever Kneeling Twist', 'waist', 'abs', '["obliques","lower back"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.","Grasp the handles or the sides of the machine for stability.","Keeping your core engaged, twist your torso to one side as far as comfortably possible.","Pause for a moment, then slowly return to the starting position.","Repeat the twist to the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपने घुटनों को पैड पर टिकाकर और अपने शरीर के ऊपरी हिस्से को आगे की ओर रखते हुए अपने आप को मशीन पर रखें।","स्थिरता के लिए मशीन के हैंडल या किनारों को पकड़ें।","अपने कोर को व्यस्त रखते हुए, जहां तक ​​संभव हो आराम से अपने धड़ को एक तरफ मोड़ें।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","मोड़ को विपरीत दिशा में दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0584', 'Lever Lateral Raise', 'shoulders', 'delts', '["traps","upper back"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Exhale and raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने रखते हुए खुद को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी भुजाओं को सीधा रखें।","साँस छोड़ें और अपनी भुजाओं को बगल की ओर तब तक उठाएँ जब तक वे फर्श के समानांतर न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0585', 'Lever Leg Extension', 'upper legs', 'quads', '["hamstrings"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and backrest of the machine to fit your body.","Sit on the machine with your back against the backrest and your feet on the footpad.","Grasp the handles or sidebars for stability.","Extend your legs forward by straightening your knees, lifting the weight.","Pause for a moment at the top, then slowly lower the weight back to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन की सीट की ऊंचाई और बैकरेस्ट को अपने शरीर के अनुरूप समायोजित करें।","मशीन पर अपनी पीठ बैकरेस्ट से सटाकर और अपने पैरों को फ़ुटपैड पर रखकर बैठें।","स्थिरता के लिए हैंडल या साइडबार को पकड़ें।","अपने घुटनों को सीधा करके, वजन उठाते हुए अपने पैरों को आगे की ओर फैलाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे वजन वापस प्रारंभिक स्थिति में लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-0586', 'Lever Lying Leg Curl', 'upper legs', 'hamstrings', '["calves"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to fit your body and select the desired weight.","Lie face down on the machine with your legs straight and your heels against the padded lever.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने शरीर के अनुरूप मशीन को समायोजित करें और वांछित वजन का चयन करें।","मशीन पर अपने पैरों को सीधा करके और अपनी एड़ियों को गद्देदार लीवर के सामने रखकर लेटें।","स्थिरता के लिए मशीन के हैंडल या किनारों को पकड़ें।","अपने ऊपरी शरीर को स्थिर रखते हुए, सांस छोड़ें और अपने कूल्हों को पैड से ऊपर उठाए बिना अपने पैरों को जितना संभव हो सके ऊपर की ओर मोड़ें।","जब आप अपनी हैमस्ट्रिंग को निचोड़ें तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे लीवर को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-3195', 'Lever Lying Two-One Leg Curl', 'upper legs', 'hamstrings', '["glutes"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your legs on the lever pad, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper body still, exhale and curl your legs up towards your glutes.","Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपने शरीर के अनुरूप समायोजित करें और अपनी पीठ को पीछे की ओर टिकाकर उस पर बैठें।","अपने पैरों को अपने टखनों के ठीक ऊपर, लीवर पैड पर रखें।","समर्थन के लिए मशीन के किनारों पर लगे हैंडल को पकड़ें।","अपने ऊपरी शरीर को स्थिर रखते हुए, सांस छोड़ें और अपने पैरों को अपने ग्लूट्स की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0587', 'Lever Military Press', 'shoulders', 'delts', '["triceps","upper chest"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को बैकरेस्ट के सामने रखते हुए खुद को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएं तब तक हैंडल को ऊपर की ओर दबाएं, लेकिन अपनी कोहनियों को लॉक न करें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0588', 'Lever Narrow Grip Seated Row', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and footrests to ensure proper form.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with a narrow grip, palms facing each other.","Keep your back straight and lean slightly forward.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]', '["उचित रूप सुनिश्चित करने के लिए सीट की ऊंचाई और फुटरेस्ट को समायोजित करें।","अपने पैरों को फ़ुटरेस्ट पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर मशीन पर बैठें।","हैंडल को पतली पकड़ से पकड़ें, हथेलियाँ एक दूसरे के सामने हों।","अपनी पीठ सीधी रखें और थोड़ा आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपने धड़ की ओर खींचें।","आंदोलन के चरम पर एक क्षण के लिए रुकें।","धीरे-धीरे हैंडल को छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0589', 'Lever One Arm Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.","Bend forward at the hips, keeping your back straight and your head up.","Let the barbell hang in front of you with your arms fully extended.","Pull the barbell up towards your chest, keeping your elbows close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी पीठ सीधी और सिर ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें।","अपनी बाहों को पूरी तरह फैलाकर बारबेल को अपने सामने लटका रहने दें।","अपनी कोहनियों को अपने शरीर के पास रखते हुए, बारबेल को अपनी छाती की ओर ऊपर खींचें।","आंदोलन के शीर्ष पर अपने कंधे के ब्लेड को एक साथ निचोड़ें।","बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1356', 'Lever One Arm Lateral High Row', 'back', 'upper back', '["biceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself facing the machine.","Grasp the handle with one hand and keep your back straight.","Pull the handle towards your body, keeping your elbow close to your side.","Squeeze your back muscles at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और अपने आप को मशीन के सामने रखें।","एक हाथ से हैंडल को पकड़ें और अपनी पीठ सीधी रखें।","अपनी कोहनी को अपनी तरफ रखते हुए, हैंडल को अपने शरीर की ओर खींचें।","आंदोलन के शीर्ष पर अपनी पीठ की मांसपेशियों को निचोड़ें।","धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1347', 'Lever One Arm Lateral Wide Pulldown', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.","Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.","Slowly return the handle to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch sides."]', '["सीट की ऊंचाई को समायोजित करें और अपनी छाती को पैड के सामने रखते हुए और अपने पैरों को फर्श पर सपाट रखते हुए अपने आप को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी कोहनी को थोड़ा मोड़ते हुए अपनी बांह को पूरी तरह फैलाएं।","हैंडल को नीचे और अपने शरीर के पार अपने विपरीत कूल्हे की ओर खींचें, आंदोलन के निचले भाग में अपनी लैट मांसपेशी को निचोड़ें।","अपने हाथ को पूरी तरह फैलाते हुए धीरे-धीरे हैंडल को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0590', 'Lever One Arm Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the lever handle with one hand and position your elbow at a 90-degree angle.","Press the lever upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the lever back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने रखते हुए खुद को मशीन पर रखें।","एक हाथ से लीवर हैंडल को पकड़ें और अपनी कोहनी को 90 डिग्री के कोण पर रखें।","लीवर को तब तक ऊपर की ओर दबाएं जब तक कि आपका हाथ पूरी तरह से ऊपर की ओर न फैल जाए।","शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे लीवर को प्रारंभिक स्थिति में वापस नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0591', 'Lever Overhand Triceps Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to the appropriate height and secure your body in position.","Grasp the handles with an overhand grip and position your body so that your arms are fully extended.","Lower your body by bending your elbows, keeping your upper arms close to your sides.","Continue lowering until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]', '["मशीन को उचित ऊंचाई पर समायोजित करें और अपने शरीर को स्थिति में सुरक्षित करें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपने शरीर को इस तरह रखें कि आपकी बाहें पूरी तरह फैली हुई हों।","अपनी कोहनियों को मोड़कर अपने शरीर को नीचे लाएँ, अपनी ऊपरी भुजाओं को अपनी भुजाओं के पास रखें।","तब तक नीचे उतरना जारी रखें जब तक आपकी ऊपरी भुजाएँ फर्श के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर अपनी कोहनियों को फैलाकर खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0592', 'Lever Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the pad and grip the handles with an underhand grip.","Keep your back straight and your elbows positioned on the pad.","Exhale and curl your forearms towards your upper arms, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और स्वयं को लीवरेज मशीन पर रखें।","अपनी ऊपरी भुजाओं को पैड पर रखें और हैंडल को अंडरहैंड ग्रिप से पकड़ें।","अपनी पीठ सीधी रखें और अपनी कोहनियाँ पैड पर रखें।","साँस छोड़ें और अपने अग्रबाहुओं को ऊपरी भुजाओं की ओर मोड़ें, अपने बाइसेप्स को सिकोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1614', 'Lever Preacher Curl v. 2', 'upper arms', 'biceps', '["forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale as you slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी ऊपरी बांहों को पैड पर और अपनी छाती को सहारे के सहारे मशीन पर रखें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए हैंडल को अपने कंधों की ओर मोड़ते हुए सांस छोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","साँस लेते हुए आप धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2285', 'Lever Pullover', 'back', 'lats', '["triceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat and handles of the leverage machine to a comfortable position.","Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Keep your arms slightly bent and your core engaged.","Slowly pull the handles towards your chest, squeezing your lats.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन की सीट और हैंडल को आरामदायक स्थिति में समायोजित करें।","मशीन पर पैड से पीठ टिकाकर बैठें और हैंडल को ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को थोड़ा झुकाकर रखें और अपने कोर को व्यस्त रखें।","अपने लैट्स को निचोड़ते हुए धीरे-धीरे हैंडल को अपनी छाती की ओर खींचें।","संकुचन के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2736', 'Lever Reverse Grip Lateral Pulldown', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपने घुटनों को पैड के नीचे और पैरों को जमीन पर सपाट रखते हुए मशीन पर खुद को रखें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी छाती को बाहर और कंधों को पीछे की ओर रखते हुए सीधे बैठें, अपनी पीठ के निचले हिस्से में हल्का सा आर्क बनाए रखें।","हैंडल को अपनी छाती की ओर नीचे खींचें, अपनी कोहनियों की मदद से आगे बढ़ें और अपने कंधे के ब्लेड को एक साथ दबाएं।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1616', 'Lever Reverse Grip Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with an underhand grip, palms facing up.","Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और स्वयं को लीवरेज मशीन पर रखें।","हैंडल को हाथ से पकड़ें, हथेलियाँ ऊपर की ओर।","अपनी ऊपरी भुजाओं को उपदेशक पैड पर रखें, यह सुनिश्चित करते हुए कि आपकी कोहनियाँ पूरी तरह फैली हुई हैं।","अपनी ऊपरी बांहों को स्थिर रखते हुए सांस छोड़ें और हैंडल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी कोहनियों को पूरी तरह फैलाते हुए हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1348', 'Lever Reverse Grip Vertical Row', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an underhand grip, palms facing up.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["उचित संरेखण सुनिश्चित करने के लिए सीट की ऊंचाई और फ़ुटप्लेट की स्थिति को समायोजित करें।","अपनी छाती को पैड से सटाकर और अपने पैरों को फ़ुटप्लेट पर सपाट करके मशीन पर बैठें।","हैंडल को हाथ से पकड़ें, हथेलियाँ ऊपर की ओर।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी छाती की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे छोड़ें और अपनी भुजाओं को प्रारंभिक स्थिति में वापस फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0593', 'Lever Reverse Hyperextension', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'leverage machine', 'strength', NULL, '["Adjust the leverage machine to fit your body and secure your feet in the foot pads.","Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Cross your arms over your chest or place them behind your head.","Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने शरीर को फिट करने और अपने पैरों को फुट पैड में सुरक्षित करने के लिए लीवरेज मशीन को समायोजित करें।","मशीन पर चेहरा नीचे करके लेटें, आपका ऊपरी शरीर किनारे से लटका हुआ हो और आपके कूल्हे पैड पर टिके हों।","अपनी बाहों को अपनी छाती के ऊपर से क्रॉस करें या उन्हें अपने सिर के पीछे रखें।","अपने पैरों को ऊपर की ओर उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को संलग्न करें जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1349', 'Lever Reverse T-Bar Row', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and footplate position on the leverage machine.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन पर सीट की ऊंचाई और फ़ुटप्लेट की स्थिति को समायोजित करें।","अपनी छाती को पैड से सटाकर और अपने पैरों को फ़ुटप्लेट पर सपाट करके मशीन पर बैठें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी छाती की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे छोड़ें और अपनी भुजाओं को प्रारंभिक स्थिति में वापस फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2315', 'Lever Rotary Calf', 'lower legs', 'calves', '["soleus","ankle stabilizers"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate, with your heels hanging off the edge.","Grasp the handles or the sides of the machine for stability.","Push through the balls of your feet, raising your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊँचाई को समायोजित करें ताकि आपके घुटने थोड़े मुड़े हुए हों और आपके पैर फ़ुटप्लेट पर सपाट हों।","अपने पैर की उंगलियों को फ़ुटप्लेट पर रखें, आपकी एड़ियाँ किनारे से लटकती रहें।","स्थिरता के लिए मशीन के हैंडल या किनारों को पकड़ें।","अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाते हुए, अपने पैरों की उंगलियों से धक्का दें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2335', 'Lever Seated Calf Press', 'lower legs', 'calves', '["soleus","hamstrings"]', 'leverage machine', 'strength', NULL, '["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.","Place your toes on the lower portion of the platform and position your knees under the lever pad.","Grasp the handles on the sides of the seat for stability.","Press the lever pad down by extending your ankles, lifting your heels as high as possible.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन की सीट को समायोजित करें ताकि आपके कंधे लीवर पैड के साथ संरेखित हों।","अपने पैर की उंगलियों को प्लेटफॉर्म के निचले हिस्से पर रखें और अपने घुटनों को लीवर पैड के नीचे रखें।","स्थिरता के लिए सीट के किनारों पर लगे हैंडल को पकड़ें।","अपनी एड़ियों को जितना संभव हो सके ऊपर उठाते हुए, अपनी एड़ियों को फैलाकर लीवर पैड को नीचे दबाएं।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0594', 'Lever Seated Calf Raise', 'lower legs', 'calves', '["soleus","ankle stabilizers"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate with your heels hanging off the edge.","Grasp the handles or the sides of the seat for stability.","Push through the balls of your feet to raise your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊँचाई को समायोजित करें ताकि आपके घुटने थोड़े मुड़े हुए हों और आपके पैर फ़ुटप्लेट पर सपाट हों।","अपने पैर की उंगलियों को फ़ुटप्लेट पर रखें और आपकी एड़ियाँ किनारे से लटकी हुई हों।","स्थिरता के लिए सीट के हैंडल या किनारों को पकड़ें।","अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाने के लिए अपने पैरों की उंगलियों से धक्का दें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1452', 'Lever Seated Crunch', 'waist', 'abs', '["obliques"]', 'leverage machine', 'strength', NULL, '["Sit on the leverage machine with your back against the pad and your feet flat on the floor.","Grasp the handles or place your hands on the side pads for support.","Engage your abs and slowly lean back, allowing the pad to move with you.","Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को फर्श पर सपाट करके बैठें।","हैंडल को पकड़ें या समर्थन के लिए अपने हाथों को साइड पैड पर रखें।","अपने पेट को संलग्न करें और धीरे-धीरे पीछे झुकें, जिससे पैड आपके साथ चल सके।","एक बार जब आपका ऊपरी शरीर 45 डिग्री के कोण पर हो, तो अपने पेट को सिकोड़ें और अपनी छाती को अपने घुटनों की ओर लाते हुए आगे की ओर झुकें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0595', 'Lever Seated Crunch (Chest Pad)', 'waist', 'abs', '["obliques"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and chest pad position according to your comfort.","Sit on the machine with your back against the chest pad and your feet flat on the floor.","Grasp the handles or side bars for stability.","Engage your abs and slowly lean back, allowing the chest pad to move with you.","Pause for a moment at the maximum contraction, feeling the tension in your abs.","Slowly return to the starting position by contracting your abs and pulling yourself back up.","Repeat for the desired number of repetitions."]', '["अपनी सुविधा के अनुसार सीट की ऊंचाई और चेस्ट पैड की स्थिति को समायोजित करें।","मशीन पर अपनी पीठ चेस्ट पैड से सटाकर बैठें और आपके पैर फर्श पर सपाट हों।","स्थिरता के लिए हैंडल या साइड बार को पकड़ें।","अपने पेट को संलग्न करें और धीरे-धीरे पीछे झुकें, जिससे छाती पैड आपके साथ चल सके।","अपने पेट में तनाव महसूस करते हुए, अधिकतम संकुचन पर एक पल के लिए रुकें।","अपने पेट को सिकोड़कर और खुद को वापस ऊपर खींचकर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3760', 'Lever Seated Crunch v. 2', 'waist', 'abs', '["obliques","hip flexors"]', 'leverage machine', 'strength', NULL, '["Sit on the leverage machine with your back against the pad and your feet secured under the footpads.","Place your hands on the handles or the sides of the seat for support.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly return to the starting position, allowing your back to round slightly.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन पर अपनी पीठ पैड से सटाकर और अपने पैरों को फ़ुटपैड के नीचे सुरक्षित करके बैठें।","समर्थन के लिए अपने हाथों को सीट के हैंडल या किनारों पर रखें।","अपने पेट को संलग्न करें और अपनी छाती को अपने घुटनों की ओर लाते हुए धीरे-धीरे आगे की ओर झुकें।","अपने पेट को सिकोड़ते हुए गति के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे प्रारंभिक स्थिति में लौट आएं, अपनी पीठ को थोड़ा गोल होने दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1451', 'Lever Seated Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.","Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें ताकि आपके पैर जमीन पर सपाट हों और आपके घुटने 90 डिग्री के कोण पर हों।","अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर लीवरेज मशीन के हैंडल को पकड़ें।","अपनी कोहनियों को मोड़कर धीरे-धीरे अपने शरीर को नीचे लाएं जब तक कि आपकी ऊपरी भुजाएं जमीन के समानांतर न हो जाएं।","एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0596', 'Lever Seated Fly', 'chest', 'pectorals', '["deltoids","trapezius"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with a pronated grip and keep your elbows slightly bent.","Exhale and push the handles forward, bringing them together in front of your chest.","Pause for a moment, squeezing your chest muscles.","Inhale and slowly return to the starting position, allowing your chest muscles to stretch.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने रखते हुए खुद को मशीन पर रखें।","हैंडल को उभरी हुई पकड़ से पकड़ें और अपनी कोहनियों को थोड़ा मोड़कर रखें।","साँस छोड़ें और हैंडल को आगे की ओर धकेलें, उन्हें अपनी छाती के सामने एक साथ लाएँ।","अपनी छाती की मांसपेशियों को निचोड़ते हुए एक क्षण रुकें।","श्वास लें और धीरे-धीरे प्रारंभिक स्थिति में लौट आएं, जिससे आपकी छाती की मांसपेशियों में खिंचाव हो।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3759', 'Lever Seated Good Morning', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height so that your hips are slightly higher than your knees.","Sit on the machine with your back against the pad and your feet flat on the footrests.","Grasp the handles or the sides of the seat for stability.","Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.","Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें ताकि आपके कूल्हे आपके घुटनों से थोड़े ऊंचे हों।","मशीन पर अपनी पीठ पैड से सटाकर बैठें और आपके पैर फुटरेस्ट पर सीधे हों।","स्थिरता के लिए सीट के हैंडल या किनारों को पकड़ें।","अपनी पीठ को सीधा रखते हुए धीरे-धीरे अपने कूल्हों से आगे की ओर झुकें जब तक कि आपका ऊपरी शरीर ज़मीन के समानांतर न हो जाए।","एक पल के लिए रुकें, फिर धीरे-धीरे अपने ग्लूट्स और हैमस्ट्रिंग पर दबाव डालते हुए प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0597', 'Lever Seated Hip Abduction', 'upper legs', 'abductors', '["glutes","hamstrings"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height so that your knees are at a 90-degree angle.","Sit on the machine with your back against the backrest and your feet on the footrests.","Place your hands on the side handles for stability.","Engage your abductors and slowly push your legs apart, away from the midline of your body.","Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें ताकि आपके घुटने 90 डिग्री के कोण पर हों।","मशीन पर अपनी पीठ बैकरेस्ट पर और पैरों को फुटरेस्ट पर रखकर बैठें।","स्थिरता के लिए अपने हाथों को साइड हैंडल पर रखें।","अपने अपहरणकर्ताओं को संलग्न करें और धीरे-धीरे अपने पैरों को अपने शरीर की मध्य रेखा से दूर धकेलें।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0598', 'Lever Seated Hip Adduction', 'upper legs', 'adductors', '["hamstrings","glutes"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the backrest.","Place your feet on the footrests and grasp the handles for stability.","Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को बैकरेस्ट के सामने रखते हुए खुद को मशीन पर रखें।","स्थिरता के लिए अपने पैरों को फुटरेस्ट पर रखें और हैंडल को पकड़ें।","अपनी योजक मांसपेशियों को संलग्न करें और धीरे-धीरे अपने पैरों को एक साथ लाएं, अपनी आंतरिक जांघों को निचोड़ें।","संकुचन के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0599', 'Lever Seated Leg Curl', 'upper legs', 'hamstrings', '["calves"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your lower legs under the padded lever, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper legs stationary, exhale and curl your legs up as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपने शरीर के अनुरूप समायोजित करें और अपनी पीठ को पीछे की ओर टिकाकर उस पर बैठें।","अपने निचले पैरों को गद्देदार लीवर के नीचे, अपने टखनों के ठीक ऊपर रखें।","समर्थन के लिए मशीन के किनारों पर लगे हैंडल को पकड़ें।","अपने ऊपरी पैरों को स्थिर रखते हुए, सांस छोड़ें और जहां तक ​​संभव हो अपने पैरों को ऊपर की ओर मोड़ें।","जब आप अपनी हैमस्ट्रिंग को निचोड़ें तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे लीवर को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0600', 'Lever Seated Leg Raise Crunch', 'waist', 'abs', '["hip flexors"]', 'leverage machine', 'strength', NULL, '["Sit on the leverage machine with your back against the backrest and your feet on the footrests.","Grasp the handles or sidebars for stability.","Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.","Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन पर अपनी पीठ को बैकरेस्ट पर और अपने पैरों को फुटरेस्ट पर रखकर बैठें।","स्थिरता के लिए हैंडल या साइडबार को पकड़ें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने पैरों को अपनी छाती की ओर ऊपर उठाएं, साथ ही अपने धड़ को आगे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों और धड़ को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0602', 'Lever Seated Reverse Fly', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी छाती को पैड के सामने रखते हुए और अपने पैरों को फर्श पर सपाट रखते हुए अपने आप को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी बाहों को थोड़ा मोड़कर रखें।","साँस छोड़ें और अपने कंधे के ब्लेड को एक साथ निचोड़ें क्योंकि आप हैंडल को अपने शरीर से दूर, पीछे और बाहर की ओर खींचते हैं।","संकुचन के चरम पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0601', 'Lever Seated Reverse Fly (Parallel Grip)', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी छाती को पैड के सामने रखते हुए और अपने पैरों को फर्श पर सपाट रखते हुए अपने आप को मशीन पर रखें।","हैंडल को समानांतर पकड़ से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों, और अपनी भुजाओं को थोड़ा मोड़कर रखें।","साँस छोड़ें और अपने कंधे के ब्लेड को एक साथ निचोड़ें क्योंकि आप हैंडल को अपने शरीर से दूर, पीछे और बाहर की ओर खींचते हैं।","संकुचन के चरम पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1350', 'Lever Seated Row', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and footrests to a comfortable position.","Sit on the machine with your chest against the pad and your feet on the footrests.","Grasp the handles with an overhand grip, shoulder-width apart.","Keep your back straight and your core engaged.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई और फुटरेस्ट को आरामदायक स्थिति में समायोजित करें।","अपनी छाती को पैड से सटाकर और अपने पैरों को पायदान पर रखकर मशीन पर बैठें।","हैंडल को कंधे की चौड़ाई की दूरी पर ओवरहैंड ग्रिप से पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपने शरीर की ओर खींचें।","आंदोलन के चरम पर एक क्षण के लिए रुकें।","धीरे-धीरे हैंडल को छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1385', 'Lever Seated Squat Calf Raise On Leg Press Machine', 'lower legs', 'calves', '["quadriceps","hamstrings","glutes"]', 'leverage machine', 'strength', NULL, '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.","Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.","Release the safety handles and push the footplate away from you by extending your knees.","Once your knees are fully extended, slowly lower your heels by flexing your calves.","Pause for a moment at the bottom, then push the footplate back up by extending your calves.","Repeat for the desired number of repetitions."]', '["लेग प्रेस मशीन की सीट को समायोजित करें ताकि जब आपके पैर फ़ुटप्लेट पर हों तो आपके घुटने थोड़े मुड़े हुए हों।","मशीन पर अपनी पीठ बैकरेस्ट से सटाकर बैठें और आपके पैर फ़ुटप्लेट पर कंधे की चौड़ाई से अलग हों।","अपनी एड़ियों को किनारे से दूर रखते हुए अपने पैर की उंगलियों और पैरों की उंगलियों को फ़ुटप्लेट पर रखें।","सुरक्षा हैंडल को छोड़ें और अपने घुटनों को फैलाकर फ़ुटप्लेट को अपने से दूर धकेलें।","एक बार जब आपके घुटने पूरी तरह से फैल जाएं, तो अपनी पिंडलियों को मोड़ते हुए धीरे-धीरे अपनी एड़ियों को नीचे लाएं।","नीचे एक पल के लिए रुकें, फिर अपनी पिंडलियों को फैलाकर फ़ुटप्लेट को वापस ऊपर की ओर धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0603', 'Lever Shoulder Press', 'shoulders', 'delts', '["triceps","chest"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands at shoulder level.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को बैकरेस्ट के सामने रखते हुए खुद को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपने हाथों को कंधे के स्तर पर रखें।","जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएं तब तक हैंडल को ऊपर की ओर दबाएं, लेकिन अपनी कोहनियों को लॉक न करें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0869', 'Lever Shoulder Press v. 2', 'shoulders', 'delts', '["triceps","chest"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन की सीट की ऊंचाई और बैकरेस्ट को आरामदायक स्थिति में समायोजित करें।","मशीन पर अपनी पीठ को पीछे की ओर टिकाकर बैठें और आपके पैर फर्श पर सपाट हों।","मशीन के हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","हैंडल को ऊपर और आगे की ओर तब तक धकेलें जब तक कि आपकी बाहें पूरी तरह विस्तारित न हो जाएं, लेकिन लॉक न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2318', 'Lever Shoulder Press v. 3', 'shoulders', 'delts', '["triceps","chest"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["लीवरेज मशीन की सीट की ऊंचाई और बैकरेस्ट को आरामदायक स्थिति में समायोजित करें।","मशीन पर अपनी पीठ को पीछे की ओर टिकाकर बैठें और आपके पैर फर्श पर सपाट हों।","मशीन के हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","हैंडल को ऊपर और आगे की ओर तब तक धकेलें जब तक कि आपकी बाहें पूरी तरह विस्तारित न हो जाएं, लेकिन लॉक न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0604', 'Lever Shrug', 'back', 'traps', '["shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the leverage machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और पैड के खिलाफ अपनी पीठ के साथ लीवरेज मशीन पर खुद को रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी भुजाओं को सीधा रखें।","अपनी पीठ को सीधा रखते हुए, अपने कंधों को अपने कानों की ओर जितना संभव हो उतना ऊपर उठाएं।","एक क्षण के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0605', 'Lever Standing Calf Raise', 'lower legs', 'calves', '["soleus","ankle stabilizers"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to your height and stand with your feet shoulder-width apart.","Place your shoulders under the pads and hold onto the handles for stability.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपनी ऊंचाई के अनुसार समायोजित करें और अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं।","स्थिरता के लिए अपने कंधों को पैड के नीचे रखें और हैंडल को पकड़ें।","अपनी एड़ियों को फैलाकर जितना हो सके अपनी एड़ियों को ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-3758', 'Lever Standing Chest Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Grasp the handles with an overhand grip and position your hands at chest level.","Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपने पैरों को जमीन पर सपाट रखते हुए खुद को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपने हाथों को छाती के स्तर पर रखें।","जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएं, तब तक हैंडल को आगे की ओर धकेलें, अपनी कोहनियों को थोड़ा मोड़कर रखें।","एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को अपनी छाती की ओर वापस लाएं, जिससे पूरी गतिविधि पर नियंत्रण बना रहे।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0606', 'Lever T Bar Row', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["उचित संरेखण सुनिश्चित करने के लिए सीट की ऊंचाई और फ़ुटप्लेट की स्थिति को समायोजित करें।","अपनी छाती को पैड से सटाकर और अपने पैरों को फ़ुटप्लेट पर सपाट करके मशीन पर बैठें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपने धड़ की ओर खींचें।","चरम संकुचन पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1351', 'Lever T-Bar Reverse Grip Row', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी छाती को पैड के सामने रखते हुए और अपने पैरों को फर्श पर सपाट रखते हुए अपने आप को मशीन पर रखें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी छाती की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे छोड़ें और अपनी भुजाओं को प्रारंभिक स्थिति में वापस फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0607', 'Lever Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and fully extend your arms in front of you.","Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.","Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने रखते हुए खुद को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी बाहों को पूरी तरह से अपने सामने फैलाएं।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे हैंडल को अपने माथे की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को फैलाकर हैंडल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1313', 'Lever Unilateral Row', 'back', 'upper back', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself facing the machine.","Grasp the handles with an overhand grip and keep your back straight.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई समायोजित करें और अपने आप को मशीन के सामने रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी पीठ सीधी रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपने शरीर की ओर खींचें।","गति के चरम पर एक क्षण के लिए रुकें, फिर धीरे-धीरे छोड़ें और अपनी भुजाओं को प्रारंभिक स्थिति में वापस फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0609', 'London Bridge', 'back', 'upper back', '["shoulders","biceps","forearms"]', 'rope', 'strength', NULL, '["Attach the rope to a high anchor point.","Stand facing away from the anchor point with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Lean forward slightly, keeping your back straight and core engaged.","Pull the rope towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["रस्सी को ऊँचे लंगर बिंदु से जोड़ दें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट से दूर की ओर मुंह करके खड़े हो जाएं।","रस्सी को हाथ से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी पीठ सीधी और कोर व्यस्त रखते हुए थोड़ा आगे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए रस्सी को अपने शरीर की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-3013', 'Low Glute Bridge On Floor', 'upper legs', 'glutes', '["hamstrings","core"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your arms by your sides, palms facing down.","Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी भुजाओं को बगल में रखें, हथेलियाँ नीचे की ओर हों।","अपने ग्लूट्स और कोर को संलग्न करें, फिर अपने कूल्हों को ज़मीन से ऊपर उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, अपने ग्लूट्स को निचोड़ें।","धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1352', 'Lower Back Curl', 'back', 'spine', '["glutes","hamstrings"]', 'body weight', 'strength', 'beginner', '["Lie flat on your stomach with your legs extended and your arms by your sides.","Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपने पेट के बल लेट जाएँ।","अपने ग्लूट्स और हैमस्ट्रिंग को संलग्न करें, और अपनी पीठ को ऊपर की ओर मोड़ते हुए धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Lower_Back_Curl/0.jpg","Lower_Back_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3582', 'Lunge With Jump', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Land softly with your left foot forward and immediately lower your body into a lunge position.","Continue alternating between lunges and jumps for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े होकर शुरुआत करें।","अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं।","अपने दाहिने पैर से धक्का दें और हवा में कूदें, अपने पैरों की स्थिति को हवा के बीच में बदलें।","अपने बाएँ पैर को आगे की ओर रखते हुए धीरे से उतरें और तुरंत अपने शरीर को नीचे की ओर झुकाएँ स्थिति में ले आएँ।","दोहराव की वांछित संख्या के लिए फेफड़ों और छलांग के बीच बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1688', 'Lunge With Twist', 'waist', 'abs', '["quadriceps","glutes","hamstrings"]', 'body weight', 'strength', NULL, '["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Pause for a moment, then return to the starting position.","Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े होकर शुरुआत करें।","अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं।","जैसे ही आप आगे बढ़ते हैं, अपने धड़ को दाईं ओर मोड़ें, अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर लाएं।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं, अपने बाएं पैर से आगे बढ़ें और अपने धड़ को बाईं ओर मोड़ें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0613', 'Lying (Side) Quads Stretch', 'upper legs', 'quads', '["hamstrings"]', 'body weight', 'strength', NULL, '["Lie on your side with your legs straight.","Bend your top leg and grab your ankle or foot with your hand.","Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]', '["अपने पैरों को सीधा करके अपनी तरफ लेटें।","अपने ऊपरी पैर को मोड़ें और अपने टखने या पैर को अपने हाथ से पकड़ें।","धीरे से अपने टखने या पैर को अपने ग्लूट्स की ओर खींचें जब तक कि आप अपने क्वाड्स में खिंचाव महसूस न करें।","20-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2312', 'Lying Elbow To Knee', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, extend your right leg straight out and lift it off the ground.","Pause for a moment, then return to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को संलग्न करें और अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, अपनी दाहिनी कोहनी को अपने बाएं घुटने की ओर लाएं।","साथ ही, अपने दाहिने पैर को सीधा फैलाएं और जमीन से ऊपर उठाएं।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","इस क्रिया को दोहराएं, इस बार अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर लाएं और अपने बाएं पैर को फैलाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0620', 'Lying Leg Raise Flat Bench', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', 'beginner', '["Lie flat on a flat bench with your back pressed against it.","Place your hands under your glutes for support.","Keep your legs straight and together, and lift them up towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक सपाट बेंच पर अपनी पीठ को टिकाकर सीधे लेट जाएं।","समर्थन के लिए अपने हाथों को अपने ग्लूट्स के नीचे रखें।","अपने पैरों को सीधा और एक साथ रखें और उन्हें छत की ओर ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Flat_Bench_Lying_Leg_Raise/0.jpg","Flat_Bench_Lying_Leg_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0865', 'Lying Leg-Hip Raise', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, raising them towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","समर्थन के लिए अपने हाथों को अपने ग्लूट्स के नीचे रखें।","अपने कोर को संलग्न करें और अपने पैरों को जमीन से ऊपर उठाएं, उन्हें छत की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1301', 'Machine Inner Chest Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपनी पीठ को पैड के सामने सपाट रखते हुए अपने आप को मशीन पर रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी कोहनियों को 90 डिग्री के कोण पर रखें।","हैंडल को तब तक आगे की ओर धकेलें जब तक कि आपकी भुजाएं पूरी तरह से विस्तारित न हो जाएं, आंदोलन के दौरान सांस छोड़ें।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे सांस लेते हुए प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0624', 'March Sit (Wall)', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your back against a wall and your feet hip-width apart.","Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Lift your right foot off the ground and bring your knee towards your chest.","Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Continue alternating between lifting your right and left foot for the desired number of repetitions."]', '["अपनी पीठ को दीवार से सटाकर और अपने पैरों को कूल्हे की चौड़ाई से अलग करके खड़े हो जाएं।","धीरे-धीरे अपनी पीठ को दीवार से नीचे की ओर खिसकाएं जब तक कि आपके घुटने 90 डिग्री के कोण पर न मुड़ जाएं।","अपने दाहिने पैर को जमीन से ऊपर उठाएं और अपने घुटने को अपनी छाती की ओर लाएं।","अपने दाहिने पैर को वापस नीचे लाएँ और अपने बाएँ पैर को ज़मीन से ऊपर उठाएँ, अपने घुटने को अपनी छाती की ओर लाएँ।","दोहराव की वांछित संख्या के लिए अपने दाएं और बाएं पैर को बारी-बारी से उठाना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1353', 'Medicine Ball Catch And Overhead Throw', 'back', 'lats', '["shoulders","core"]', 'medicine ball', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.","Bend your knees slightly and engage your core.","Lower your body into a squat position, keeping your back straight and chest up.","Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.","Release the ball at the top of the movement and catch it on the way down.","Lower your body back into the squat position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों में छाती के स्तर पर एक मेडिसिन बॉल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें।","अपनी पीठ सीधी और छाती ऊपर रखते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","अपने कूल्हों और पैरों को तेजी से फैलाएं, साथ ही दवा की गेंद को ऊपर की ओर फेंकें।","गेंद को गति के शीर्ष पर छोड़ें और नीचे आते समय पकड़ें।","अपने शरीर को वापस स्क्वाट स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1302', 'Medicine Ball Chest Pass', 'chest', 'pectorals', '["shoulders","triceps"]', 'medicine ball', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest with force.","As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.","Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.","Continue for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, दवा की गेंद को छाती के स्तर पर पकड़ें।","अपनी बाहों को आगे बढ़ाएं, दवा की गेंद को बलपूर्वक अपनी छाती से दूर धकेलें।","जैसे ही आप गेंद को छोड़ते हैं, अपनी भुजाओं और धड़ के साथ आगे बढ़ें, अपने वजन को अपने पिछले पैर से अपने सामने के पैर पर स्थानांतरित करें।","जैसे ही गेंद दीवार या साथी से टकराकर उछलती है, उसे पकड़ें और तुरंत यही क्रिया दोहराएँ।","दोहराव की वांछित संख्या के लिए जारी रखें।"]', '["Medicine_Ball_Chest_Pass/0.jpg","Medicine_Ball_Chest_Pass/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1303', 'Medicine Ball Chest Push From 3 Point Stance', 'chest', 'pectorals', '["shoulders","triceps"]', 'medicine ball', 'strength', NULL, '["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Extend your legs and position your body in a straight line.","Lower your chest towards the ground while keeping your back straight.","Push the medicine ball away from your body, extending your arm fully.","Return to the starting position and repeat for the desired number of repetitions."]', '["एक हाथ मेडिसिन बॉल पर और दूसरा हाथ ज़मीन पर रखकर 3 पॉइंट स्टांस में शुरुआत करें।","अपने पैरों को फैलाएं और अपने शरीर को एक सीधी रेखा में रखें।","अपनी पीठ सीधी रखते हुए अपनी छाती को ज़मीन की ओर नीचे करें।","अपनी बांह को पूरी तरह फैलाकर दवा की गेंद को अपने शरीर से दूर धकेलें।","प्रारंभिक स्थिति पर लौटें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1304', 'Medicine Ball Chest Push Multiple Response', 'chest', 'pectorals', '["triceps","shoulders"]', 'medicine ball', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर, छाती के स्तर पर एक मेडिसिन बॉल पकड़कर खड़े रहें।","अपनी बाहों को आगे बढ़ाएं, दवा की गेंद को अपनी छाती से दूर धकेलें।","एक पल के लिए रुकें, फिर धीरे-धीरे दवा की गेंद को वापस अपनी छाती पर लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1305', 'Medicine Ball Chest Push Single Response', 'chest', 'pectorals', '["triceps","shoulders"]', 'medicine ball', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, दवा की गेंद को छाती के स्तर पर पकड़ें।","अपनी बाहों को आगे बढ़ाएं, दवा की गेंद को अपनी छाती से दूर धकेलें।","एक पल के लिए रुकें, फिर धीरे-धीरे दवा की गेंद को वापस अपनी छाती पर लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1312', 'Medicine Ball Chest Push With Run Release', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'medicine ball', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","As you push the ball forward, release it and let it roll forward.","Quickly run forward and catch the ball before it hits the ground.","Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.","Continue alternating legs and repeating the exercise for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर, छाती के स्तर पर एक मेडिसिन बॉल पकड़कर खड़े रहें।","अपने दाहिने पैर से आगे बढ़ें और साथ ही अपनी बाहों को पूरी तरह फैलाते हुए मेडिसिन बॉल को आगे की ओर धकेलें।","जैसे ही आप गेंद को आगे की ओर धकेलें, उसे छोड़ दें और आगे की ओर लुढ़कने दें।","तेजी से आगे दौड़ें और गेंद को जमीन पर गिरने से पहले पकड़ लें।","एक बार जब आप गेंद को पकड़ लें, तो उसे वापस अपनी छाती पर लाएँ और अपने बाएँ पैर को आगे की ओर रखते हुए इस क्रिया को दोहराएँ।","पैरों को बारी-बारी से बदलते रहें और व्यायाम को वांछित संख्या में दोहराव तक दोहराते रहें।"]', NULL, 9.8, 'sets', 0, 'opengym', 1),
('og-1701', 'Medicine Ball Close Grip Push Up', 'upper arms', 'triceps', '["chest","shoulders"]', 'medicine ball', 'strength', NULL, '["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को मेडिसिन बॉल पर कंधे-चौड़ाई की दूरी पर रखकर ऊंची तख़्त स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए वापस प्रारंभिक स्थिति में आएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1354', 'Medicine Ball Overhead Slam', 'back', 'upper back', '["shoulders","core"]', 'medicine ball', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.","Engage your core and keep your back straight.","Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.","As you slam the ball down, use your entire body to generate power, including your shoulders and core.","Catch the ball on the bounce and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपने सिर के ऊपर दोनों हाथों से एक मेडिसिन बॉल पकड़ें।","अपने कोर को व्यस्त रखें और अपनी पीठ सीधी रखें।","अपने घुटनों को थोड़ा मोड़ें और दवा की गेंद को अपने सामने जमीन पर जोर से पटकें।","जैसे ही आप गेंद को नीचे पटकते हैं, अपने कंधों और कोर सहित, शक्ति उत्पन्न करने के लिए अपने पूरे शरीर का उपयोग करें।","उछाल पर गेंद को पकड़ें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1750', 'Medicine Ball Supine Chest Throw', 'upper arms', 'triceps', '["chest","shoulders"]', 'medicine ball', 'strength', NULL, '["Lie flat on your back on a bench with your knees bent and feet flat on the ground.","Hold the medicine ball with both hands, extending your arms straight up above your chest.","Lower the medicine ball towards your chest, keeping your elbows close to your body.","Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.","Catch the medicine ball and repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए एक बेंच पर अपनी पीठ के बल लेट जाएँ।","दवा की गेंद को दोनों हाथों से पकड़ें, अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी कोहनियों को अपने शरीर के पास रखते हुए मेडिसिन बॉल को अपनी छाती की ओर नीचे करें।","दवा की गेंद को विस्फोटक तरीके से ऊपर की ओर धकेलें, अपनी बाहों को पूरी तरह फैलाएं और गेंद को जितना संभव हो उतना ऊपर फेंकें।","मेडिसिन बॉल को पकड़ें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0627', 'Mixed Grip Chin-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["पुल-अप बार को अंडरहैंड ग्रिप से पकड़ें (हथेलियाँ आपकी ओर हों) और आपके हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को ज़मीन से ऊपर रखते हुए बार से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को नियंत्रण के साथ प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3217', 'Modified Hindu Push-Up (Male)', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Lower your body towards the ground, bending your elbows and keeping your core engaged.","As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा और अपने पैरों को कूल्हे की चौड़ाई से थोड़ा अलग रखते हुए पुश-अप स्थिति से शुरुआत करें।","अपने शरीर को ज़मीन की ओर नीचे करें, अपनी कोहनियों को मोड़ें और अपने कोर को व्यस्त रखें।","जैसे ही आप अपने शरीर को नीचे लाते हैं, अपना वजन पीछे ले जाएं और अपने कूल्हों को छत की ओर ऊपर उठाएं, जिससे आपके शरीर के साथ एक उलटा वी आकार बन जाए।","अपने शरीर को तब तक नीचे झुकाते रहें जब तक कि आपकी छाती ज़मीन के ठीक ऊपर न आ जाए, फिर गति को उलट दें, अपने कूल्हों को पीछे की ओर धकेलें और अपनी बाहों को फैलाकर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1421', 'Modified Push Up To Lower Arms', 'lower arms', 'forearms', '["triceps","chest","shoulders"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को एक सीधी रेखा में रखकर पुश-अप स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","एक बार जब आपकी कोहनियाँ 90 डिग्री के कोण पर आ जाएँ, तो अपनी कोहनियों को सीधे अपने कंधों के नीचे रखते हुए, अपने अग्रबाहुओं को ज़मीन पर टिकाएँ।","एक पल के लिए रुकें, फिर अपनी हथेलियों से धक्का देकर अपने अग्रबाहुओं को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0628', 'Monster Walk', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'body weight', 'strength', NULL, '["Place a resistance band around your ankles.","Stand with your feet shoulder-width apart and slightly bend your knees.","Take a step to the side with your right foot, maintaining tension on the resistance band.","Follow with your left foot, stepping to the side to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपनी एड़ियों के चारों ओर एक प्रतिरोध बैंड लगाएं।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने घुटनों को थोड़ा मोड़ लें।","प्रतिरोध बैंड पर तनाव बनाए रखते हुए, अपने दाहिने पैर के साथ एक कदम आगे बढ़ें।","प्रारंभिक स्थिति में लौटने के लिए अपने बाएं पैर का अनुसरण करें, बगल की ओर बढ़ते हुए।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 3.5, 'sets', 0, 'opengym', 1),
('og-0630', 'Mountain Climber', 'cardio', 'cardiovascular system', '["core","shoulders","triceps"]', 'body weight', 'cardio', NULL, '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपने दाहिने घुटने को अपनी छाती की ओर लाएँ, फिर जल्दी से स्विच करें और अपने बाएँ घुटने को अपनी छाती की ओर लाएँ।","अपने कूल्हों को नीचे और अपने कोर को व्यस्त रखते हुए पैरों को बारी-बारी से चलाना जारी रखें।","पूरे अभ्यास के दौरान स्थिर गति बनाए रखें और समान रूप से सांस लें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-0631', 'Muscle Up', 'back', 'lats', '["biceps","triceps","shoulders","chest"]', 'body weight', 'strength', NULL, '["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.","Reverse the movement by slowly lowering yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को आपसे दूर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर एक पुल-अप बार से लटककर शुरुआत करें।","अपने कोर को संलग्न करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए बार की ओर ऊपर खींचें।","जैसे ही आप गति के शीर्ष पर पहुँचते हैं, अपनी पकड़ को बदलें ताकि आपकी हथेलियाँ आपकी ओर हों।","अपने आप को तब तक ऊपर खींचते रहें जब तक कि आपकी छाती बार के ऊपर न आ जाए और आपकी बाहें पूरी तरह से मुड़ न जाएं।","धीरे-धीरे अपने आप को प्रारंभिक स्थिति में वापस लाकर गति को उलट दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1401', 'Muscle-Up (On Vertical Bar)', 'back', 'lats', '["biceps","triceps","forearms"]', 'body weight', 'strength', NULL, '["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Continue pulling until your chest reaches the bar and your elbows are fully bent.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को आपसे दूर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर एक ऊर्ध्वाधर पट्टी से लटकना शुरू करें।","अपने कोर को संलग्न करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए बार की ओर ऊपर खींचें।","जैसे ही आप अपने आप को ऊपर खींचते हैं, थोड़ा पीछे झुकें और अपनी कोहनियों को अपनी तरफ लाएँ।","तब तक खींचते रहें जब तक कि आपकी छाती बार तक न पहुंच जाए और आपकी कोहनी पूरी तरह मुड़ न जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2328', 'Narrow Push-Up On Exercise Ball', 'upper arms', 'triceps', '["chest","shoulders"]', 'stability ball', 'strength', NULL, '["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ball by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल को जमीन पर रखें और अपने हाथों को कंधे की चौड़ाई से थोड़ा संकरा करके बॉल पर रखकर खुद को पुश-अप स्थिति में रखें।","अपने कोर को व्यस्त रखें और अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखें।","अपनी कोहनियों को मोड़कर, उन्हें अपने शरीर के पास रखते हुए, अपनी छाती को गेंद की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1403', 'Neck Side Stretch', 'neck', 'levator scapulae', '["trapezius","sternocleidomastoid"]', 'body weight', 'strength', NULL, '["Stand or sit up straight with your shoulders relaxed.","Tilt your head to one side, bringing your ear towards your shoulder.","Hold the stretch for 15-30 seconds.","Repeat on the other side.","Perform 2-4 sets on each side."]', '["अपने कंधों को आराम देते हुए सीधे खड़े हों या बैठें।","अपने सिर को एक तरफ झुकाएं, अपने कान को अपने कंधे की ओर लाएं।","15-30 सेकंड तक खिंचाव बनाए रखें।","दूसरी तरफ दोहराएं।","प्रत्येक तरफ 2-4 सेट करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0634', 'Negative Crunch', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1495', 'Oblique Crunch v. 2', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', NULL, '["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेटें।","अपने हाथों को अपने सिर के पीछे रखें या उन्हें अपनी छाती के ऊपर से पार करें।","अपने पेट को संलग्न करें और अपने धड़ को एक तरफ घुमाते हुए अपने कंधे के ब्लेड को जमीन से ऊपर उठाएं।","एक पल के लिए रुकें, फिर अपने कंधे के ब्लेड को वापस प्रारंभिक स्थिति में ले आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0635', 'Oblique Crunches Floor', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', 'beginner', '["Lie on your back with your knees bent and feet flat on the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the floor.","Repeat on the other side, alternating sides with each repetition."]', '["अपने घुटनों को मोड़कर और पैरों को फर्श पर सपाट रखते हुए अपनी पीठ के बल लेटें।","अपने हाथों को अपने सिर के पीछे रखें या उन्हें अपनी छाती के ऊपर से पार करें।","अपने पेट को संलग्न करें और अपने धड़ को एक तरफ घुमाते हुए अपने कंधे के ब्लेड को फर्श से ऊपर उठाएं।","एक पल के लिए रुकें, फिर अपने कंधे के ब्लेड को वापस फर्श पर नीचे लाएँ।","प्रत्येक पुनरावृत्ति के साथ पक्षों को बदलते हुए, दूसरी तरफ दोहराएं।"]', '["Oblique_Crunches_-_On_The_Floor/0.jpg","Oblique_Crunches_-_On_The_Floor/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0636', 'Olympic Barbell Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'olympic barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.","Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और ओलंपिक बारबेल को ओवरहैंड ग्रिप से पकड़ लें।","अपनी हथेलियों को अपने शरीर की ओर रखते हुए, बारबेल को अपनी जांघों के सामने एक हाथ की दूरी पर लटका रहने दें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0637', 'Olympic Barbell Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'olympic barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े होकर और बारबेल को ऊपरी पकड़ से पकड़कर शुरुआत करें।","अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को अपने सिर के ऊपर उठाएं।","अपनी ऊपरी भुजाओं को अपने सिर के पास रखते हुए, अपनी कोहनियों को मोड़कर बारबेल को धीरे-धीरे अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1355', 'One Arm Against Wall', 'back', 'lats', '["shoulders","triceps"]', 'body weight', 'strength', NULL, '["Stand facing a wall with your feet shoulder-width apart.","Extend one arm straight out in front of you and place your palm against the wall.","Engage your core and lean your body forward, keeping your arm straight and your back flat.","Slowly push against the wall with your palm, activating your lat muscles.","Hold the position for a few seconds, then release and repeat with the other arm."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए दीवार की ओर मुंह करके खड़े हो जाएं।","एक हाथ को अपने सामने सीधा फैलाएं और अपनी हथेली को दीवार से सटाकर रखें।","अपने कोर को संलग्न करें और अपने शरीर को आगे की ओर झुकाएं, अपनी बांह को सीधा और अपनी पीठ को सपाट रखें।","धीरे-धीरे अपनी हथेली से दीवार को धक्का दें, जिससे आपकी अंडकोश की मांसपेशियां सक्रिय हो जाएंगी।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर छोड़ें और दूसरे हाथ से दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0638', 'One Arm Chin-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand facing a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.","Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.","Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए पुल-अप बार की ओर मुंह करके खड़े हो जाएं।","ऊपर पहुंचें और बार को अंडरहैंड ग्रिप से पकड़ें, एक हाथ से बार को पकड़ें और दूसरे हाथ से सहारे के लिए अपनी कलाई को पकड़ें।","अपने हाथ को पूरी तरह फैलाकर, अपने शरीर को सीधा और अपने कोर को व्यस्त रखते हुए बार से लटकें।","अपनी कोहनी मोड़कर और अपनी पीठ की मांसपेशियों को निचोड़कर अपने आप को बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक कि आपकी ठुड्डी बार के ऊपर न आ जाए, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0639', 'One Arm Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Stand facing away from a bench or chair, with your feet shoulder-width apart.","Place one hand on the bench or chair behind you, fingers pointing towards your body.","Extend your legs out in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए, किसी बेंच या कुर्सी से दूर की ओर मुंह करके खड़े हो जाएं।","एक हाथ अपने पीछे बेंच या कुर्सी पर रखें, उंगलियाँ आपके शरीर की ओर हों।","अपनी एड़ियों को ज़मीन पर रखते हुए, अपने पैरों को अपने सामने फैलाएँ।","अपनी कोहनियों को मोड़ें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी पीठ को बेंच या कुर्सी के पास रखें।","नीचे एक पल के लिए रुकें, फिर अपनी हथेलियों से धक्का देकर अपनी भुजाओं को सीधा करें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें और दूसरे हाथ से दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0640', 'One Arm Slam (With Medicine Ball)', 'waist', 'abs', '["shoulders","back"]', 'medicine ball', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.","Bend your knees slightly and engage your core.","Raise the medicine ball above your head, fully extending your arm.","Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.","Catch the medicine ball on the bounce and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ से मेडिसिन बॉल को अपनी कमर के सामने पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें।","अपनी बांह को पूरी तरह फैलाते हुए मेडिसिन बॉल को अपने सिर के ऊपर उठाएं।","शक्ति उत्पन्न करने के लिए अपने कोर और कंधों का उपयोग करते हुए दवा की गेंद को जबरदस्ती जमीन पर पटकें।","उछाल पर दवा की गेंद को पकड़ें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', '["One-Arm_Medicine_Ball_Slam/0.jpg","One-Arm_Medicine_Ball_Slam/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1773', 'One Arm Towel Row', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm fully, allowing the towel to hang in front of you.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और एक हाथ से तौलिया पकड़ लें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कमर के बल आगे की ओर झुकें।","अपनी बांह को पूरी तरह फैलाएं, जिससे तौलिया आपके सामने लटक जाए।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, तौलिये को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तौलिये को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1386', 'One Leg Donkey Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a stable surface for support, such as a wall or a bar.","Lift one leg off the ground, keeping your knee slightly bent.","Raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां आगे की ओर हों।","अपने हाथों को सहारे के लिए किसी स्थिर सतह, जैसे दीवार या बार पर रखें।","अपने घुटने को थोड़ा मोड़ते हुए एक पैर को जमीन से ऊपर उठाएं।","अपनी पिंडली की मांसपेशियों का उपयोग करते हुए अपनी एड़ी को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1387', 'One Leg Floor Calf Raise', 'lower legs', 'calves', '["ankles","feet"]', 'body weight', 'strength', NULL, '["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["अपने पैरों को कूल्हे की चौड़ाई के बराबर फैलाकर खड़े हो जाएं और संतुलन के लिए अपने हाथों को किसी दीवार या मजबूत वस्तु पर रखें।","एक पैर को जमीन से ऊपर उठाएं और दूसरे पैर पर संतुलन बनाएं।","धीरे-धीरे अपनी एड़ी को जमीन से ऊपर उठाएं, अपने शरीर को अपने पैर की गेंद पर ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1476', 'One Leg Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Extend one leg forward, keeping it off the ground.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Push through your heel to return to the starting position.","Repeat with the other leg."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","एक पैर को जमीन से ऊपर रखते हुए आगे बढ़ाएं।","अपने खड़े पैर को मोड़ें और अपने शरीर को नीचे नीचे करें जैसे कि कुर्सी पर पीछे बैठे हों।","अपनी छाती ऊपर और पीठ सीधी रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ी को धक्का दें।","दूसरे पैर से दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0641', 'Otis Up', 'waist', 'abs', '["hip flexors","lower back"]', 'weighted', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0642', 'Outside Leg Kick Push-Up', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Continue alternating leg kicks and push-ups for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा और अपने पैरों को एक साथ रखकर पुश-अप स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा और कोर को व्यस्त रखते हुए अपने शरीर को जमीन की ओर नीचे लाएं।","जैसे ही आप पीछे की ओर धकेलते हैं, एक पैर को किनारे की ओर लात मारें, इसे पूरी तरह फैलाएं और अपने ग्लूट्स को शामिल करें।","अपने पैर को प्रारंभिक स्थिति में लौटाएँ और प्रत्येक पुनरावृत्ति के साथ पैरों को बारी-बारी से पुश-अप दोहराएं।","पुनरावृत्ति की वांछित संख्या के लिए बारी-बारी से लेग किक और पुश-अप जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0643', 'Overhead Triceps Stretch', 'upper arms', 'triceps', '["shoulders"]', 'body weight', 'strength', NULL, '["Stand or sit upright with your feet shoulder-width apart.","Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हों या बैठें।","एक हाथ को ऊपर की ओर फैलाएं, कोहनी पर झुकें ताकि आपका हाथ विपरीत कंधे के ब्लेड तक पहुंच जाए।","अपने दूसरे हाथ से, अपने ट्राइसेप्स में खिंचाव महसूस करते हुए, विस्तारित भुजा की कोहनी को धीरे से अपने सिर के विपरीत दिशा की ओर खींचें।","15-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3147', 'Pelvic Tilt', 'waist', 'abs', '["lower back"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides.","Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Hold this position for a few seconds, focusing on contracting your abs.","Release the tilt and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने बगल में रखें।","अपने पेट को संलग्न करें और अपनी श्रोणि को ऊपर की ओर झुकाएं, अपनी पीठ के निचले हिस्से को जमीन पर दबाएं।","अपने पेट को सिकोड़ने पर ध्यान केंद्रित करते हुए कुछ सेकंड के लिए इस स्थिति में रहें।","झुकाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1422', 'Pelvic Tilt Into Bridge', 'upper legs', 'glutes', '["hamstrings","core"]', 'body weight', 'strength', NULL, '["Lie on your back with your knees bent and feet flat on the ground.","Place your arms by your sides with your palms facing down.","Engage your glutes and core muscles.","Tilt your pelvis upward, lifting your hips off the ground.","Hold the bridge position for a few seconds.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेटें।","अपनी हथेलियों को नीचे की ओर रखते हुए अपनी भुजाओं को बगल में रखें।","अपने ग्लूट्स और कोर मांसपेशियों को संलग्न करें।","अपने कूल्हों को ज़मीन से ऊपर उठाते हुए, अपने श्रोणि को ऊपर की ओर झुकाएँ।","कुछ सेकंड के लिए पुल की स्थिति में रहें।","धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1388', 'Peroneals Stretch', 'lower legs', 'calves', '["ankles","feet"]', 'rope', 'strength', NULL, '["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 15-30 seconds.","Release the tension on the rope and repeat the stretch on the other leg.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सामने फैलाकर जमीन पर बैठें।","रस्सी को अपने पैर की गेंद के चारों ओर लपेटें और रस्सी के सिरों को अपने हाथों से पकड़ें।","अपने पैर को मोड़ते हुए और अपनी पिंडली की मांसपेशियों को खींचते हुए धीरे से रस्सी को अपनी ओर खींचें।","15-30 सेकंड तक खिंचाव बनाए रखें।","रस्सी पर तनाव छोड़ें और दूसरे पैर पर खिंचाव दोहराएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3662', 'Pike-To-Cobra Push-Up', 'upper legs', 'glutes', '["core","shoulders","triceps"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.","Lower your upper body towards the ground by bending your elbows, keeping them close to your body.","As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.","Reverse the movement by bending your elbows and lowering your chest back down towards the ground.","Push through your hands to return to the inverted V position.","Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा और अपने पैरों को एक साथ रखकर पुश-अप स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपने कूल्हों को छत की ओर ऊपर उठाएं, जिससे आपके शरीर के साथ एक उलटा वी आकार बन जाए।","अपनी कोहनियों को मोड़कर, उन्हें अपने शरीर के करीब रखते हुए, अपने ऊपरी शरीर को ज़मीन की ओर नीचे लाएँ।","जैसे ही आप नीचे आते हैं, अपना वजन आगे बढ़ाएं और अपनी बाहों को सीधा करके और अपनी छाती को ऊपर उठाकर कोबरा मुद्रा में आ जाएं।","अपनी कोहनियों को मोड़कर और अपनी छाती को वापस ज़मीन की ओर झुकाकर गति को उल्टा करें।","उल्टे V स्थिति में लौटने के लिए अपने हाथों से धक्का दें।","अपने कूल्हों को वापस ज़मीन की ओर नीचे करके, प्रारंभिक पुश-अप स्थिति में लौटकर आंदोलन जारी रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1306', 'Plyo Push Up', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'body weight', 'strength', 'beginner', '["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.","Push explosively off the ground, using your chest muscles to propel your upper body off the ground.","Land softly with your hands back in the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखते हुए एक ऊंचे तख़्ते की स्थिति से शुरुआत करें।","अपने शरीर को सीधी रेखा में रखते हुए, अपनी कोहनियों को मोड़कर अपनी छाती को ज़मीन की ओर नीचे करें।","अपने ऊपरी शरीर को ज़मीन से ऊपर उठाने के लिए अपनी छाती की मांसपेशियों का उपयोग करते हुए, ज़मीन से ज़ोर से धक्का दें।","अपने हाथों को प्रारंभिक स्थिति में वापस लाते हुए धीरे से जमीन पर उतरें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Plyo_Push-up/0.jpg","Plyo_Push-up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1687', 'Posterior Step To Overhead Reach', 'waist', 'abs', '["glutes","hamstrings","quadriceps","shoulders"]', 'body weight', 'strength', NULL, '["Stand with your feet hip-width apart and your arms by your sides.","Take a step back with your right foot, landing on the ball of your foot.","Bend your left knee and lower your body into a lunge position.","As you lower into the lunge, simultaneously reach your arms overhead.","Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके और अपनी बाहों को अपने बगल में रखकर खड़े हो जाएं।","अपने दाहिने पैर से एक कदम पीछे हटें, अपने पैर की गेंद पर उतरें।","अपने बाएं घुटने को मोड़ें और अपने शरीर को लंज स्थिति में नीचे लाएं।","जैसे ही आप लंज में नीचे आते हैं, साथ ही अपनी बाहों को ऊपर की ओर ले जाएं।","लंज के निचले हिस्से में एक पल के लिए रुकें, फिर अपनी बाईं एड़ी से धक्का देकर और अपने दाहिने पैर को आगे लाकर प्रारंभिक स्थिति में लौट आएं।","इस क्रिया को दूसरी तरफ दोहराएं, अपने बाएं पैर से पीछे हटें और अपने दाहिने घुटने को मोड़ें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1389', 'Posterior Tibialis Stretch', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'rope', 'strength', NULL, '["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 20-30 seconds.","Release the tension on the rope and relax your foot.","Repeat the stretch on the other leg."]', '["अपने पैरों को सामने फैलाकर जमीन पर बैठें।","रस्सी को अपने पैर की गेंद के चारों ओर लपेटें और रस्सी के सिरों को अपने हाथों से पकड़ें।","अपने पैर को मोड़ते हुए और अपनी पिंडली की मांसपेशियों को खींचते हुए धीरे से रस्सी को अपनी ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","रस्सी पर तनाव छोड़ें और अपने पैर को आराम दें।","दूसरे पैर पर खिंचाव दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3119', 'Potty Squat', 'waist', 'abs', '["quadriceps","glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Keep your chest up and your back straight throughout the movement.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को नीचे झुकाएँ जैसे कि आप एक कुर्सी पर बैठे हों।","पूरे आंदोलन के दौरान अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें।","अपने आप को तब तक नीचे करें जब तक कि आपकी जांघें ज़मीन के समानांतर न हों या जितना नीचे आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3132', 'Potty Squat With Support', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold onto a stable support, such as a chair or wall, for balance.","Lower your body down into a squat position by bending your knees and pushing your hips back.","Keep your chest up and your back straight throughout the movement.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","संतुलन के लिए कुर्सी या दीवार जैसे किसी स्थिर सहारे को पकड़ें।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","पूरे आंदोलन के दौरान अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0648', 'Power Clean', 'upper legs', 'hamstrings', '["glutes","quadriceps","calves"]', 'barbell', 'strength', 'intermediate', '["Start with the barbell on the ground in front of you, with your feet shoulder-width apart.","Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.","As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.","Stand up with the barbell, fully extending your hips and knees.","Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए, अपने सामने ज़मीन पर बारबेल से शुरुआत करें।","नीचे झुकें और बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","बारबेल को ज़मीन से उठाते समय अपनी पीठ सीधी और छाती ऊपर रखें, अपने कूल्हों और घुटनों को फैलाएँ।","जैसे ही बारबेल आपकी मध्य-जाँघ तक पहुँचती है, इसे विस्फोटक रूप से ऊपर की ओर खींचें, अपने कंधों को सिकोड़ें और अपनी कोहनियों को ऊँचा और बगल की ओर खींचें।","जैसे ही बारबेल अपने उच्चतम बिंदु पर पहुंचता है, जल्दी से इसके नीचे आ जाएं, अपनी कोहनियों को चारों ओर घुमाएं और फ्रंट स्क्वाट स्थिति में बारबेल को अपने कंधों पर पकड़ लें।","अपने कूल्हों और घुटनों को पूरी तरह फैलाते हुए बारबेल के साथ खड़े हो जाएं।","पूरे आंदोलन के दौरान वजन पर नियंत्रण रखते हुए, बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Power_Clean/0.jpg","Power_Clean/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3665', 'Power Point Plank', 'waist', 'abs', '["shoulders","triceps","glutes"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and squeeze your glutes to maintain a stable position.","Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Hold this position for the desired amount of time, keeping your core and glutes engaged.","To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखते हुए एक ऊंची तख़्त स्थिति में शुरुआत करें।","स्थिर स्थिति बनाए रखने के लिए अपने कोर को संलग्न करें और अपने ग्लूट्स को निचोड़ें।","सिर से पैर तक एक सीधी रेखा बनाए रखते हुए, अपने शरीर को अपने अग्रबाहुओं पर, एक समय में एक हाथ पर नीचे लाएँ।","अपने कोर और ग्लूट्स को व्यस्त रखते हुए, वांछित समय तक इस स्थिति में रहें।","शुरुआती स्थिति में लौटने के लिए, अपने अग्रबाहुओं को धक्का दें और अपने शरीर को वापस ऊंचे तख़्ते की स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3203', 'Prisoner Half Sit-Up (Male)', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1707', 'Prone Twist On Stability Ball', 'waist', 'abs', '["obliques","lower back"]', 'stability ball', 'strength', NULL, '["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Place your hands behind your head or cross them over your chest.","Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Pause for a moment, then return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखें और अपने पैरों की उंगलियों को जमीन को छूते हुए एक स्टेबिलिटी बॉल पर मुंह के बल लेटकर शुरुआत करें।","अपने हाथों को अपने सिर के पीछे रखें या उन्हें अपनी छाती के ऊपर से पार करें।","अपनी मुख्य मांसपेशियों को शामिल करें और अपनी पीठ को सीधा रखते हुए धीरे-धीरे अपने ऊपरी शरीर को गेंद से ऊपर उठाएं।","अपने धड़ को एक तरफ घुमाएं, अपने कंधे को अपने कूल्हे की ओर लाएं। पूरे आंदोलन के दौरान अपने कूल्हों और पैरों को स्थिर रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरी ओर भी घुमाएँ दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0651', 'Pull Up (Neutral Grip)', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["पुल-अप बार से तटस्थ पकड़ (हथेलियाँ एक दूसरे के सामने) के साथ लटकें और आपकी भुजाएँ पूरी तरह फैली हुई हों।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ें।","अपनी कोहनियों को मोड़कर अपने शरीर को बार की ओर ऊपर खींचें और अपनी कोहनियों को अपने कूल्हों की ओर नीचे ले जाएं।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को नियंत्रण के साथ प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0650', 'Pull-In (On Stability Ball)', 'waist', 'abs', '["hip flexors"]', 'stability ball', 'strength', NULL, '["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the sides of the stability ball for support.","Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.","Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर स्टेबिलिटी बॉल पर बैठकर शुरुआत करें।","समर्थन के लिए अपने हाथों को स्टेबिलिटी बॉल के किनारों पर रखें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने कूल्हों को आगे की ओर घुमाएं, अपने घुटनों को अपनी छाती की ओर लाएं।","गति के शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे अपने पैरों को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0652', 'Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को आपसे दूर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर एक पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ें।","अपनी कोहनियों को मोड़कर और अपनी छाती को बार की ओर लाकर अपने शरीर को बार की ओर ऊपर खींचें।","गति के शीर्ष पर रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-1689', 'Push And Pull Bodyweight', 'chest', 'pectorals', '["triceps","deltoids"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा करके और अपने शरीर को एक सीधी रेखा में रखकर पुश-अप स्थिति से शुरुआत करें।","अपने शरीर को सीधा रखते हुए, अपनी कोहनियों को मोड़कर अपनी छाती को ज़मीन की ओर नीचे करें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","पुश-अप स्थिति से, अपने शरीर को सीधा रखते हुए, अपनी कोहनियों को मोड़कर अपनी छाती को जमीन की ओर खींचें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3638', 'Push To Run', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your hands to extend your arms and return to the starting position.","Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating knees as fast as you can while maintaining good form.","Continue for the desired duration or number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई पर और अपने शरीर को एक सीधी रेखा में रखकर पुश-अप स्थिति से शुरुआत करें।","अपने शरीर को सीधा रखते हुए, अपनी कोहनियों को मोड़कर अपनी छाती को ज़मीन की ओर नीचे करें।","अपनी भुजाओं को फैलाने के लिए अपने हाथों से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","जल्दी से एक घुटने को अपनी छाती की ओर लाएँ, फिर तेज़ी से बदलें और दूसरे घुटने को अपनी छाती की ओर लाएँ।","अच्छी स्थिति बनाए रखते हुए घुटनों को जितनी तेजी से संभव हो सके बदलना जारी रखें।","वांछित अवधि या दोहराव की संख्या तक जारी रखें।"]', NULL, 9.8, 'time', 0, 'opengym', 1),
('og-1307', 'Push Up On Bosu Ball', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'bosu ball', 'strength', NULL, '["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["बोसु बॉल को समतल भाग ऊपर की ओर रखते हुए जमीन पर रखें।","अपने हाथों को बोसु बॉल के बाहरी किनारों पर रखते हुए खुद को पुश-अप स्थिति में रखें।","अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर अपने शरीर को बोसु बॉल की ओर नीचे करें।","अपनी भुजाओं को फैलाकर अपने आप को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0662', 'Push-Up', 'chest', 'pectorals', '["triceps","deltoids","core"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.","Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा और अपने पैरों को एक साथ मिलाकर एक ऊंचे तख़्ते की स्थिति से शुरुआत करें।","अपने कोर को संलग्न करें और अपने शरीर को एक सीधी रेखा में रखते हुए, अपनी कोहनियों को मोड़कर जमीन की ओर नीचे करें।","जब आपकी छाती ज़मीन से ठीक ऊपर हो तो एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके अपने आप को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-0653', 'Push-Up (Bosu Ball)', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'bosu ball', 'strength', NULL, '["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["बोसु बॉल को समतल भाग ऊपर की ओर रखते हुए जमीन पर रखें।","अपने हाथों को बोसु बॉल के बाहरी किनारों पर रखते हुए खुद को पुश-अप स्थिति में रखें।","अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर अपने शरीर को बोसु बॉल की ओर नीचे करें।","अपनी भुजाओं को फैलाकर अपने आप को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0655', 'Push-Up (On Stability Ball)', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'stability ball', 'strength', NULL, '["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल को जमीन पर रखें और अपने हाथों को कंधे की चौड़ाई की दूरी पर बॉल पर रखते हुए खुद को नीचे की ओर रखें।","अपने पंजों पर संतुलन बनाते हुए अपने पैरों को अपने पीछे सीधा फैलाएँ।","अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर, अपने शरीर को एक सीधी रेखा में रखते हुए, अपनी छाती को गेंद की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0656', 'Push-Up (On Stability Ball)', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'stability ball', 'strength', NULL, '["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल को जमीन पर रखें और अपने हाथों को कंधे की चौड़ाई की दूरी पर बॉल पर रखते हुए खुद को नीचे की ओर रखें।","अपने पंजों पर संतुलन बनाते हुए अपने पैरों को अपने पीछे सीधा फैलाएँ।","अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर, अपने शरीर को एक सीधी रेखा में रखते हुए, अपनी छाती को गेंद की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0659', 'Push-Up (Wall)', 'chest', 'pectorals', '["triceps","deltoids"]', 'body weight', 'strength', NULL, '["Stand facing a wall, about arm''s length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your feet hip-width apart.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push back up to the starting position, straightening your arms.","Repeat for the desired number of repetitions."]', '["एक हाथ की दूरी पर दीवार की ओर मुंह करके खड़े हो जाएं।","अपने हाथों को कंधे की ऊंचाई पर, कंधे की चौड़ाई से थोड़ा चौड़ा, दीवार पर रखें।","अपने शरीर को सीधा और पैरों को कूल्हे की चौड़ाई से अलग रखते हुए कुछ फीट पीछे हटें।","अपनी कोहनियों को मोड़ें और अपने शरीर को सीधी रेखा में रखते हुए अपनी छाती को दीवार की ओर नीचे करें।","अपनी भुजाओं को सीधा करते हुए वापस प्रारंभिक स्थिति में आ जाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0658', 'Push-Up (Wall) v. 2', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Stand facing a wall, about arm''s length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back with your feet, keeping them hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the wall, keeping your body straight.","Pause for a moment, then push yourself back to the starting position.","Repeat for the desired number of repetitions."]', '["एक हाथ की दूरी पर दीवार की ओर मुंह करके खड़े हो जाएं।","अपने हाथों को कंधे की ऊंचाई पर, कंधे की चौड़ाई से थोड़ा चौड़ा, दीवार पर रखें।","अपने पैरों को कूल्हे-चौड़ाई से अलग रखते हुए पीछे हटें।","अपने कोर को व्यस्त रखें और अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखें।","अपने शरीर को सीधा रखते हुए अपनी कोहनियों को मोड़ें और अपनी छाती को दीवार की ओर नीचे करें।","एक क्षण के लिए रुकें, फिर अपने आप को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0660', 'Push-Up Close-Grip Off Dumbbell', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', NULL, '["Start in a push-up position with your hands placed close together, directly under your shoulders.","Hold a dumbbell in each hand, resting them on the ground.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को एक-दूसरे के करीब, सीधे अपने कंधों के नीचे रखकर पुश-अप स्थिति में शुरुआत करें।","प्रत्येक हाथ में एक डम्बल पकड़ें, उन्हें ज़मीन पर टिकाएँ।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0661', 'Push-Up Inside Leg Kick', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.","As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.","Lower your leg back down and repeat the push-up, then switch to the other leg.","Continue alternating leg kicks with each push-up repetition."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा और अपने पैरों को एक साथ रखकर पुश-अप स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा और अपने कोर को व्यस्त रखते हुए, अपने शरीर को जमीन की ओर नीचे लाएँ।","जैसे ही आप पीछे की ओर धकेलते हैं, एक पैर को ज़मीन से ऊपर उठाएं और उसे सीधा रखते हुए किनारे की ओर लात मारें।","अपने पैर को वापस नीचे करें और पुश-अप दोहराएं, फिर दूसरे पैर पर स्विच करें।","प्रत्येक पुश-अप दोहराव के साथ बारी-बारी से लेग किक करना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0663', 'Push-Up Medicine Ball', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'medicine ball', 'strength', NULL, '["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को मेडिसिन बॉल पर कंधे-चौड़ाई की दूरी पर रखकर ऊंची तख़्त स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा रखते हुए अपने शरीर को जमीन की ओर नीचे करें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1467', 'Push-Up On Lower Arms', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने अग्रबाहुओं को ज़मीन पर और कोहनियों को सीधे अपने कंधों के नीचे रखते हुए तख़्त स्थिति में शुरुआत करें।","अपने कोर को व्यस्त रखें और अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखें।","अपनी कोहनियों को मोड़कर, उन्हें अपने शरीर के पास रखते हुए, अपनी छाती को ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3145', 'Push-Up Plus', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा करके और अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","एक बार जब आपकी छाती जमीन से ठीक ऊपर हो, तो अपने हाथों से धक्का देकर अपनी भुजाओं को फैलाएं और अपने ऊपरी शरीर को ऊपर उठाएं।","आंदोलन के शीर्ष पर, अपनी ऊपरी पीठ को छत की ओर धकेलते हुए अपने कंधे के ब्लेड को फैलाएं।","एक पल के लिए रुकें, फिर अपने कंधे के ब्लेड को पीछे खींचकर और अपने शरीर को वापस प्रारंभिक स्थिति में लाकर गति को उलट दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0664', 'Push-Up To Side Plank', 'waist', 'abs', '["shoulders","chest","triceps"]', 'body weight', 'strength', 'beginner', '["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push back up to the starting position.","Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Hold the side plank position for a few seconds, then return to the starting position.","Repeat the push-up and side plank on the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई पर और अपने शरीर को एक सीधी रेखा में रखकर पुश-अप स्थिति से शुरुआत करें।","अपनी कोहनियों को मोड़कर, अपने कोर को व्यस्त रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","प्रारंभिक स्थिति में वापस पुश करें।","अपना वजन अपने बाएं हाथ पर डालें और अपने शरीर को दाईं ओर घुमाएं, अपने दाहिने हाथ को छत की ओर उठाएं।","कुछ सेकंड के लिए साइड प्लैंक स्थिति में रहें, फिर प्रारंभिक स्थिति में लौट आएं।","पुश-अप और साइड प्लैंक को विपरीत दिशा में दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Push_Up_to_Side_Plank/0.jpg","Push_Up_to_Side_Plank/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-3533', 'Quads', 'upper legs', 'quads', '["hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Keep your chest up and your back straight.","Lower yourself until your thighs are parallel to the ground.","Push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को नीचे लाएँ जैसे कि आप कुर्सी पर बैठे हों।","अपनी छाती ऊपर और पीठ सीधी रखें।","अपने आप को तब तक नीचे रखें जब तक आपकी जांघें ज़मीन के समानांतर न हो जाएं।","प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3201', 'Quarter Sit-Up', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3552', 'Quick Feet v. 2', 'upper legs', 'quads', '["calves","hamstrings"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your arms by your sides.","Begin by rapidly moving your feet up and down, as if you were running in place.","Keep your movements quick and light, focusing on staying on the balls of your feet.","Continue for the desired duration or number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और अपनी बांहों को बगल में रखकर खड़े हो जाएं।","अपने पैरों को तेजी से ऊपर-नीचे हिलाने से शुरुआत करें, जैसे कि आप अपनी जगह पर दौड़ रहे हों।","अपने पैरों की उंगलियों पर ध्यान केंद्रित करते हुए अपनी गतिविधियों को तेज और हल्का रखें।","वांछित अवधि या दोहराव की संख्या तक जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0666', 'Raise Single Arm Push-Up', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Extend one arm straight out to the side, parallel to the ground.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position, using your chest muscles to lift your body.","Repeat with the other arm extended."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा और अपने पैरों को एक साथ रखकर पुश-अप स्थिति में शुरुआत करें।","एक हाथ को ज़मीन के समानांतर बगल की ओर सीधा फैलाएँ।","अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा और कोर को व्यस्त रखते हुए अपने शरीर को जमीन की ओर नीचे लाएं।","अपने शरीर को ऊपर उठाने के लिए अपनी छाती की मांसपेशियों का उपयोग करते हुए, प्रारंभिक स्थिति में वापस आएँ।","दूसरे हाथ को फैलाकर दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0668', 'Rear Decline Bridge', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'body weight', 'strength', NULL, '["Lie on your back with your feet flat on the ground and your knees bent.","Place your arms by your sides with your palms facing down.","Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर अपनी पीठ के बल लेटें।","अपनी हथेलियों को नीचे की ओर रखते हुए अपनी भुजाओं को बगल में रखें।","अपने ग्लूट्स और हैमस्ट्रिंग को संलग्न करें, और अपने कूल्हों को ज़मीन से ऊपर उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0669', 'Rear Deltoid Stretch', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'body weight', 'strength', NULL, '["Stand tall with your feet shoulder-width apart.","Extend your right arm across your chest, placing your left hand on your right elbow.","Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े रहें।","अपने दाहिने हाथ को अपनी छाती के पार फैलाएँ, अपने बाएँ हाथ को अपनी दाहिनी कोहनी पर रखें।","अपने दाहिने कंधे में खिंचाव महसूस करते हुए धीरे से अपने दाहिने हाथ को अपने बाएं कंधे की ओर खींचें।","15-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0670', 'Rear Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["पुल-अप बार को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके बार से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए अपने शरीर को बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1582', 'Reclining Big Toe Pose With Rope', 'upper legs', 'hamstrings', '["calves","glutes"]', 'rope', 'strength', NULL, '["Lie on your back with your legs extended and your arms by your sides.","Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.","Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.","Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल लेटें।","रस्सी को अपने दाहिने पैर की गेंद के चारों ओर लपेटें और रस्सी के सिरों को अपने हाथों से पकड़ें।","अपने दाहिने पैर को धीरे-धीरे अपनी छाती की ओर उठाएं, अपने घुटने को सीधा रखें और अपने पैर को मोड़ें।","कुछ सेकंड के लिए खिंचाव बनाए रखें, फिर धीरे-धीरे अपने पैर को वापस प्रारंभिक स्थिति में ले आएं।","अपने बाएँ पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3236', 'Resistance Band Hip Thrusts On Knees (Female)', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'resistance band', 'strength', NULL, '["Start by kneeling on the ground with your knees hip-width apart and your feet flexed.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on your hips or extend them out in front of you for balance.","Engage your glutes and core muscles.","Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.","Hold the position for a moment, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को कूल्हे की चौड़ाई पर फैलाकर और अपने पैरों को मोड़कर ज़मीन पर घुटनों के बल बैठकर शुरुआत करें।","प्रतिरोध बैंड को अपनी जांघों के चारों ओर, घुटनों के ठीक ऊपर लपेटें।","संतुलन के लिए अपने हाथों को अपने कूल्हों पर रखें या उन्हें अपने सामने फैलाएँ।","अपने ग्लूट्स और कोर मांसपेशियों को संलग्न करें।","अपने कूल्हों को आगे की ओर धकेलें और अपने घुटनों को ज़मीन से ऊपर उठाते हुए अपने ग्लूट्स को निचोड़ें, अपने कूल्हों को तब तक फैलाएँ जब तक कि आपकी जाँघें ज़मीन के समानांतर न हो जाएँ।","एक क्षण के लिए इस स्थिति में रहें, फिर धीरे-धीरे अपने घुटनों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3007', 'Resistance Band Leg Extension', 'upper legs', 'quads', '["hamstrings"]', 'resistance band', 'strength', NULL, '["Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Stand facing the anchor point with your feet shoulder-width apart.","Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Pause for a moment at the top, then slowly return your leg to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["प्रतिरोध बैंड को एक मजबूत लंगर बिंदु से जोड़ें और इसे अपने टखने के चारों ओर सुरक्षित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","अपने कोर को व्यस्त रखते हुए और अपने ऊपरी शरीर को स्थिर रखते हुए, अपने पैर को अपने सामने सीधा फैलाएँ।","शीर्ष पर एक क्षण के लिए रुकें, फिर धीरे-धीरे अपने पैर को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3123', 'Resistance Band Seated Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'resistance band', 'strength', NULL, '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.","Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the resistance band back to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके कुर्सी या बेंच पर बैठें।","प्रतिरोध बैंड को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और भुजाएँ बगल में नीचे की ओर फैली हुई हों।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और प्रतिरोध बैंड को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे प्रतिरोध बैंड को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3124', 'Resistance Band Seated Chest Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'resistance band', 'strength', NULL, '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Extend your arms forward, pushing the resistance band away from your chest.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके कुर्सी या बेंच पर बैठें।","प्रत्येक हाथ में प्रतिरोध बैंड के हैंडल को पकड़ें, आपकी हथेलियाँ नीचे की ओर हों और कोहनियाँ 90 डिग्री के कोण पर मुड़ी हुई हों।","अपनी बाहों को आगे बढ़ाएं, प्रतिरोध बैंड को अपनी छाती से दूर धकेलें।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3006', 'Resistance Band Seated Hip Abduction', 'upper legs', 'abductors', '["glutes","hamstrings"]', 'resistance band', 'strength', NULL, '["Sit on a chair or bench with your back straight and feet flat on the ground.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on the sides of the chair or bench for support.","Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.","Pause for a moment at the end of the movement, then slowly bring your knees back together.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके कुर्सी या बेंच पर बैठें।","प्रतिरोध बैंड को अपनी जांघों के चारों ओर, घुटनों के ठीक ऊपर लपेटें।","समर्थन के लिए अपने हाथों को कुर्सी या बेंच के किनारों पर रखें।","अपने अपहरणकर्ताओं (बाहरी जांघ की मांसपेशियों) को संलग्न करें और बैंड के प्रतिरोध के विपरीत, धीरे-धीरे अपने घुटनों को अलग करें।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे अपने घुटनों को वापस एक साथ लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3122', 'Resistance Band Seated Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'resistance band', 'strength', NULL, '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Press the band overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the band back down to shoulder level.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके कुर्सी या बेंच पर बैठें।","प्रतिरोध बैंड को दोनों हाथों से पकड़ें, हथेलियाँ आगे की ओर हों और इसे कंधे के स्तर तक लाएँ।","अपनी बाहों को पूरी तरह फैलाते हुए बैंड को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3144', 'Resistance Band Seated Straight Back Row', 'back', 'upper back', '["biceps","shoulders"]', 'resistance band', 'strength', NULL, '["Sit on the floor with your legs extended and loop the resistance band around your feet.","Hold the ends of the resistance band with your hands, palms facing each other.","Keep your back straight and lean slightly back, engaging your core.","Pull the resistance band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर फर्श पर बैठें और अपने पैरों के चारों ओर प्रतिरोध बैंड लपेटें।","प्रतिरोध बैंड के सिरों को अपने हाथों से पकड़ें, हथेलियाँ एक दूसरे के सामने हों।","अपनी पीठ सीधी रखें और अपने कोर को शामिल करते हुए थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, प्रतिरोध बैंड को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0872', 'Reverse Crunch', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your arms extended along your sides.","Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ के बल सीधे लेट जाएँ और अपनी भुजाएँ बगल में फैलाएँ।","अपने घुटनों को मोड़ें और अपने पैरों को जमीन से ऊपर उठाएं, अपनी जांघों को फर्श पर सीधा लाएं।","अपने पेट को सिकोड़ें और अपने कूल्हों को फर्श से मोड़ें, अपने घुटनों को अपनी छाती की ओर लाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Reverse_Crunch/0.jpg","Reverse_Crunch/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0672', 'Reverse Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Position yourself between two parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपनी भुजाओं को पूरी तरह फैलाकर और अपने शरीर को सीधा रखते हुए अपने आप को दो समानांतर पट्टियों के बीच रखें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ ज़मीन के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करके खुद को शुरुआती स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0673', 'Reverse Grip Machine Lat Pulldown', 'back', 'lats', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें और अपने घुटनों को पैड के नीचे और पैरों को जमीन पर सपाट रखते हुए मशीन पर खुद को रखें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी छाती को बाहर और कंधों को पीछे की ओर रखते हुए सीधे बैठें, अपनी पीठ के निचले हिस्से में हल्का सा आर्क बनाए रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0674', 'Reverse Grip Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["हाथों को कंधे की चौड़ाई से अलग रखते हुए पुल-अप बार को हाथ से पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके बार से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0675', 'Reverse Hyper Extension (On Stability Ball)', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'stability ball', 'strength', NULL, '["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for stability.","Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने कूल्हों को गेंद पर टिकाकर और अपने पैरों को अपने पीछे सीधा फैलाकर एक स्टेबिलिटी बॉल पर मुंह करके लेटें।","स्थिरता के लिए अपने हाथों को अपने सामने ज़मीन पर रखें।","अपने ग्लूट्स और हैमस्ट्रिंग को जोड़ते हुए, अपने पैरों को छत की ओर जितना हो सके ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1423', 'Reverse Hyper On Flat Bench', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'body weight', 'strength', NULL, '["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Hold onto the bench for stability.","Keeping your legs straight, raise them up towards the ceiling as high as you can.","Squeeze your glutes at the top of the movement.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक सपाट बेंच पर अपने कूल्हों को किनारे पर रखते हुए और अपने पैरों को बेंच से लटकाते हुए मुंह के बल लेटें।","स्थिरता के लिए बेंच को पकड़ें।","अपने पैरों को सीधा रखते हुए उन्हें छत की ओर जितना हो सके ऊपर उठाएं।","आंदोलन के शीर्ष पर अपने ग्लूट्स को निचोड़ें।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3663', 'Reverse Plank With Leg Lift', 'waist', 'abs', '["glutes","hamstrings","shoulders"]', 'body weight', 'strength', NULL, '["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Hold for a moment, then lower your leg back down.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["अपने पैरों को अपने सामने फैलाकर ज़मीन पर बैठें और आपके हाथ आपके पीछे ज़मीन पर टिके हों, उंगलियाँ आपके पैरों की ओर हों।","अपने हाथों से दबाएं और अपने कूल्हों को ज़मीन से ऊपर उठाएं, उलटी तख़्त स्थिति में आ जाएँ।","अपने कोर को संलग्न करें और एक पैर को जमीन से ऊपर उठाएं, इसे सीधे छत की ओर बढ़ाएं।","एक क्षण रुकें, फिर अपना पैर वापस नीचे कर लें।","दूसरे पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0677', 'Ring Dips', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Start by hanging from the rings with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा रखते हुए छल्लों से लटकना शुरू करें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपके कंधे आपकी कोहनियों से नीचे न आ जाएँ।","अपनी भुजाओं को सीधा करके स्वयं को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2571', 'Rocking Frog Stretch', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'body weight', 'strength', NULL, '["Start by kneeling on the ground with your knees hip-width apart.","Place your hands on the ground in front of you for support.","Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Hold this position for a few seconds, feeling a stretch in your glutes.","Slowly return to the starting position by bending your knees and lowering your hips back down.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को कूल्हे की चौड़ाई से अलग रखते हुए ज़मीन पर घुटने टेककर शुरुआत करें।","समर्थन के लिए अपने हाथों को अपने सामने ज़मीन पर रखें।","धीरे-धीरे आगे की ओर झुकें, अपना वजन अपने हाथों पर डालें और अपने पैरों को अपने पीछे फैलाएँ।","अपनी पीठ सीधी रखें और अपने कूल्हों को छत की ओर पीछे और ऊपर धकेलते हुए अपने ग्लूट्स को संलग्न करें।","अपने ग्लूट्स में खिंचाव महसूस करते हुए कुछ सेकंड के लिए इस स्थिति में रहें।","धीरे-धीरे अपने घुटनों को मोड़कर और अपने कूल्हों को वापस नीचे लाकर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0678', 'Rocky Pull-Up Pulldown', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand in front of a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए पुल-अप बार के सामने खड़े हो जाएं।","ऊपर पहुंचें और कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ बार को पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके बार से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए बार की ओर ऊपर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-2208', 'Roller Back Stretch', 'back', 'spine', '["hamstrings","glutes"]', 'roller', 'strength', NULL, '["Start by sitting on the ground with your legs extended in front of you.","Place the roller perpendicular to your body, just below your glutes.","Slowly roll your body backwards, allowing the roller to move up your back.","Continue rolling until the roller reaches your upper back.","Pause for a moment, then slowly roll back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को अपने सामने फैलाकर जमीन पर बैठकर शुरुआत करें।","रोलर को अपने शरीर के लंबवत रखें, अपने ग्लूट्स के ठीक नीचे।","धीरे-धीरे अपने शरीर को पीछे की ओर घुमाएं, जिससे रोलर आपकी पीठ तक ऊपर जा सके।","तब तक घुमाते रहें जब तक कि रोलर आपकी पीठ के ऊपरी हिस्से तक न पहुंच जाए।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में वापस आ जाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2204', 'Roller Body Saw', 'waist', 'abs', '["shoulders","triceps","core"]', 'roller', 'strength', NULL, '["Start in a plank position with your forearms on the roller and your body in a straight line.","Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.","Repeat for the desired number of repetitions."]', '["अपने अग्रबाहुओं को रोलर पर और अपने शरीर को एक सीधी रेखा में रखते हुए तख़्त स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और धीरे-धीरे रोलर को आगे की ओर घुमाएं, नियंत्रण बनाए रखते हुए अपने शरीर को जितना हो सके उतना फैलाएं।","सबसे दूर वाले बिंदु पर एक क्षण के लिए रुकें, फिर धीरे-धीरे रोलर को अपनी प्रारंभिक स्थिति की ओर वापस घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2205', 'Roller Hip Lat Stretch', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'roller', 'strength', NULL, '["Start by kneeling on the ground with the roller positioned under your hips.","Place your hands on the roller for support.","Slowly roll the roller forward, extending your hips and stretching your glutes.","Hold the stretch for a few seconds, then roll back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने कूल्हों के नीचे रोलर रखकर ज़मीन पर घुटने टेककर शुरुआत करें।","समर्थन के लिए अपने हाथों को रोलर पर रखें।","धीरे-धीरे रोलर को आगे की ओर घुमाएं, अपने कूल्हों को फैलाएं और अपने ग्लूट्स को फैलाएं।","कुछ सेकंड के लिए खिंचाव को रोके रखें, फिर प्रारंभिक स्थिति में वापस आ जाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2202', 'Roller Hip Stretch', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'roller', 'strength', NULL, '["Start by sitting on the ground with your legs extended in front of you.","Place the roller under your glutes, just above your knees.","Lean back and place your hands on the ground behind you for support.","Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.","Pause for a moment at the end of the movement, feeling a stretch in your glutes.","Slowly roll the roller back to the starting position, extending your legs.","Repeat for the desired number of repetitions."]', '["अपने पैरों को अपने सामने फैलाकर जमीन पर बैठकर शुरुआत करें।","रोलर को अपने घुटनों के ठीक ऊपर, अपने ग्लूट्स के नीचे रखें।","पीछे झुकें और समर्थन के लिए अपने हाथों को अपने पीछे ज़मीन पर रखें।","अपने ग्लूट्स को संलग्न करें और धीरे-धीरे रोलर को आगे की ओर घुमाएं, अपने घुटनों को मोड़ें और उन्हें अपनी छाती की ओर लाएं।","आंदोलन के अंत में एक पल के लिए रुकें, अपने ग्लूट्स में खिंचाव महसूस करें।","धीरे-धीरे अपने पैरों को फैलाते हुए रोलर को प्रारंभिक स्थिति में वापस रोल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2206', 'Roller Reverse Crunch', 'waist', 'abs', '["hip flexors"]', 'roller', 'strength', NULL, '["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.","Place the roller between your feet and grip it with your toes.","Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.","Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.","Repeat for the desired number of repetitions."]', '["अपनी पीठ के बल सीधे लेट जाएँ, अपनी बाँहों को अपने सिर के ऊपर सीधा फैलाएँ और अपने पैरों को अपने सामने सीधा फैलाएँ।","रोलर को अपने पैरों के बीच रखें और इसे अपने पैर की उंगलियों से पकड़ें।","अपने पेट को जोड़ते हुए, अपने पैरों को ज़मीन से ऊपर उठाएं और अपने घुटनों को अपनी छाती की ओर मोड़ें, रोलर को अपने शरीर की ओर घुमाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं, रोलर को अपने शरीर से दूर घुमाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2203', 'Roller Seated Shoulder Flexor Depresor Retractor', 'chest', 'pectorals', '["deltoids","triceps"]', 'roller', 'strength', NULL, '["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.","Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.","Repeat for the desired number of repetitions."]', '["अपने पैरों को अपने सामने फैलाकर समतल सतह पर बैठें।","रोलर को दोनों हाथों से पकड़ें, हथेलियाँ नीचे की ओर हों और इसे अपनी जाँघों पर रखें।","थोड़ा आगे झुकें और अपनी बाहों को अपने सामने सीधा फैलाते हुए रोलर को अपने शरीर से दूर घुमाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे रोलर को अपने शरीर की ओर वापस घुमाएं, अपनी बाहों को मोड़ें और रोलर को अपनी जांघों पर वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2209', 'Roller Seated Single Leg Shoulder Flexor Depresor Retractor', 'chest', 'pectorals', '["deltoids","triceps"]', 'roller', 'strength', NULL, '["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean back slightly and engage your core muscles.","Raise the roller up to shoulder level, keeping your arms straight.","Slowly lower the roller back down to your thighs.","Repeat for the desired number of repetitions."]', '["अपने पैरों को अपने सामने फैलाकर समतल सतह पर बैठें।","रोलर को दोनों हाथों से पकड़ें, हथेलियाँ नीचे की ओर हों और इसे अपनी जाँघों पर रखें।","थोड़ा पीछे झुकें और अपनी मुख्य मांसपेशियों को शामिल करें।","अपनी बाहों को सीधा रखते हुए रोलर को कंधे के स्तर तक उठाएं।","धीरे-धीरे रोलर को वापस अपनी जाँघों तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2207', 'Roller Side Lat Stretch', 'back', 'lats', '["shoulders","triceps"]', 'roller', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.","Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से रोलर को अपने शरीर के सामने पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी बाहों को आगे बढ़ाएं और रोलर को अपने पैरों की ओर नीचे घुमाएं, जिससे आपकी जांघों में खिंचाव महसूस हो।","कुछ सेकंड के लिए खिंचाव को रोके रखें, फिर धीरे-धीरे रोलर को प्रारंभिक स्थिति में वापस रोल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0680', 'Rope Climb', 'back', 'upper back', '["forearms","biceps","shoulders"]', 'rope', 'strength', NULL, '["Stand facing the rope with your feet shoulder-width apart.","Grab the rope with both hands, palms facing towards you.","Bend your knees slightly and engage your core.","Begin pulling yourself up the rope by alternating hand-over-hand movements.","Use your legs to assist in the upward movement.","Continue climbing until you reach the desired height or the top of the rope.","To descend, reverse the hand-over-hand movement while controlling your descent.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए रस्सी की ओर मुंह करके खड़े हो जाएं।","रस्सी को दोनों हाथों से पकड़ें, हथेलियाँ आपकी ओर हों।","अपने घुटनों को थोड़ा मोड़ें और अपने कोर को संलग्न करें।","बारी-बारी से हाथ से हाथ हिलाकर अपने आप को रस्सी पर ऊपर खींचना शुरू करें।","ऊपर की ओर बढ़ने में सहायता के लिए अपने पैरों का उपयोग करें।","तब तक चढ़ना जारी रखें जब तक आप वांछित ऊंचाई या रस्सी के शीर्ष तक नहीं पहुंच जाते।","नीचे उतरने के लिए, अपने उतरते समय को नियंत्रित करते हुए हाथ से हाथ की गति को उल्टा करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0685', 'Run', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]', '["अपने पैरों को कूल्हे की चौड़ाई के बराबर दूरी पर रखकर सीधे खड़े होकर शुरुआत करें।","अपने कोर को व्यस्त रखें और अपने ऊपरी शरीर को शिथिल रखें।","अपनी जगह पर जॉगिंग करना शुरू करें, अपने घुटनों को अपनी छाती की ओर उठाएं और धीरे से अपने पैरों की उंगलियों पर उतरें।","स्थिर गति बनाए रखें और वांछित अवधि या दूरी तक जॉगिंग जारी रखें।","याद रखें कि पूरे अभ्यास के दौरान गहरी सांस लें और अच्छी मुद्रा बनाए रखें।"]', NULL, 9.8, 'time', 0, 'opengym', 1),
('og-0684', 'Run (Equipment)', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]', '["अपने पैरों को कूल्हे की चौड़ाई के बराबर दूरी पर रखकर सीधे खड़े होकर शुरुआत करें।","अपने कोर को व्यस्त रखें और अपने ऊपरी शरीर को शिथिल रखें।","अपनी जगह पर जॉगिंग करना शुरू करें, अपने घुटनों को अपनी छाती की ओर उठाएं और धीरे से अपने पैरों की उंगलियों पर उतरें।","स्थिर गति बनाए रखें और वांछित अवधि या दूरी तक जॉगिंग जारी रखें।","याद रखें कि पूरे अभ्यास के दौरान गहरी सांस लें और अच्छी मुद्रा बनाए रखें।"]', NULL, 9.8, 'time', 0, 'opengym', 1),
('og-1585', 'Runners Stretch', 'upper legs', 'hamstrings', '["calves","quadriceps"]', 'body weight', 'strength', NULL, '["Stand with your feet hip-width apart.","Take a step forward with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down, keeping your left leg straight.","Place your hands on your right thigh for support.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े रहें।","अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने बाएं पैर को सीधा रखें।","अपने दाहिने घुटने को मोड़ें और अपने बाएं पैर को सीधा रखते हुए अपने शरीर को नीचे करें।","समर्थन के लिए अपने हाथों को अपनी दाहिनी जांघ पर रखें।","20-30 सेकंड के लिए खिंचाव बनाए रखें, फिर किनारे बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0687', 'Russian Twist', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', 'intermediate', '["Sit on the ground with your knees bent and feet flat on the floor.","Lean back slightly while keeping your back straight and your core engaged.","Hold your hands together in front of your chest or hold a weight if desired.","Lift your feet off the ground, balancing on your sit bones.","Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को फर्श पर सपाट करके जमीन पर बैठें।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए थोड़ा पीछे झुकें।","यदि चाहें तो अपने हाथों को अपनी छाती के सामने एक साथ पकड़ें या कोई वज़न पकड़ें।","अपनी बैठी हुई हड्डियों पर संतुलन बनाते हुए अपने पैरों को ज़मीन से ऊपर उठाएं।","अपने धड़ को दाहिनी ओर मोड़ें, अपने हाथों या वजन को अपने शरीर के दाहिनी ओर लाएँ।","एक पल के लिए रुकें, फिर अपने धड़ को बाईं ओर मोड़ें, अपने हाथों या वजन को अपने शरीर के बाईं ओर लाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Russian_Twist/0.jpg","Russian_Twist/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3012', 'Scapula Dips', 'back', 'traps', '["rhomboids","deltoids"]', 'body weight', 'strength', NULL, '["Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और अपनी बाहों को आपके सामने फैलाकर खड़े होकर शुरुआत करें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी कोहनियों को मोड़कर और अपने कंधे के ब्लेड को पीछे खींचकर अपने शरीर को नीचे करें, जैसे कि आप उनके बीच एक पेंसिल को दबाने की कोशिश कर रहे हों।","नीचे एक पल के लिए रुकें, फिर अपनी कोहनियों को फैलाने के लिए अपने हाथों से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3021', 'Scapula Push-Up', 'chest', 'serratus anterior', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your chest towards the ground, keeping your elbows close to your body.","As you lower, squeeze your shoulder blades together and push your chest forward.","Pause for a moment at the bottom, then push back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपनी कोहनियों को अपने शरीर के पास रखते हुए, अपनी छाती को ज़मीन की ओर झुकाएँ।","जैसे ही आप नीचे आते हैं, अपने कंधे के ब्लेड को एक साथ दबाएं और अपनी छाती को आगे की ओर धकेलें।","नीचे एक पल के लिए रुकें, फिर वापस प्रारंभिक स्थिति में आ जाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0688', 'Scapular Pull-Up', 'back', 'traps', '["biceps","rhomboids","rear deltoids"]', 'body weight', 'strength', NULL, '["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Retract your shoulder blades by pulling them down and back.","Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को आपसे दूर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर एक पुल-अप बार से लटककर शुरुआत करें।","अपने कंधे के ब्लेडों को नीचे और पीछे खींचकर पीछे खींचें।","अपनी पीठ की मांसपेशियों को संलग्न करें और अपने शरीर को बार की ओर ऊपर खींचें, अपने कंधे के ब्लेड को एक साथ निचोड़ने पर ध्यान केंद्रित करें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3219', 'Scissor Jumps (Male)', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart.","Jump off the ground and simultaneously cross your right leg in front of your left leg.","As you land, quickly switch legs, crossing your left leg in front of your right leg.","Continue alternating legs and jumping as quickly as possible.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","ज़मीन से कूदें और साथ ही अपने दाहिने पैर को अपने बाएँ पैर के सामने से पार करें।","जैसे ही आप उतरें, जल्दी से पैर बदलें, अपने बाएं पैर को अपने दाहिने पैर के सामने से पार करें।","जितनी जल्दी हो सके पैरों को बदलना और कूदना जारी रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-1390', 'Seated Calf Stretch (Male)', 'lower legs', 'calves', '["hamstrings"]', 'body weight', 'strength', NULL, '["Sit on the edge of a chair or bench with your feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]', '["अपने पैरों को ज़मीन पर सपाट करके कुर्सी या बेंच के किनारे पर बैठें।","अपनी एड़ी को ज़मीन पर रखते हुए एक पैर को अपने सामने सीधा फैलाएँ।","अपनी पिंडली की मांसपेशियों में खिंचाव महसूस करते हुए थोड़ा आगे झुकें।","20-30 सेकंड तक खिंचाव बनाए रखें।","पैर बदलें और खिंचाव दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1424', 'Seated Glute Stretch', 'upper legs', 'glutes', '["hamstrings"]', 'body weight', 'strength', NULL, '["Sit on the ground with your legs extended in front of you.","Bend your right knee and cross your right ankle over your left thigh.","Place your right hand on the ground behind you for support.","With your left hand, gently press down on your right knee to deepen the stretch.","Hold the stretch for 30 seconds to 1 minute.","Switch sides and repeat."]', '["अपने पैरों को सामने फैलाकर जमीन पर बैठें।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने टखने को अपनी बाईं जांघ के ऊपर से पार करें।","समर्थन के लिए अपना दाहिना हाथ अपने पीछे ज़मीन पर रखें।","खिंचाव को गहरा करने के लिए अपने बाएं हाथ से अपने दाहिने घुटने को धीरे से दबाएं।","30 सेकंड से 1 मिनट तक खिंचाव बनाए रखें।","पक्ष बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0689', 'Seated Leg Raise', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Sit on a flat bench with your back straight and your feet flat on the ground.","Place your hands on the sides of the bench for support.","Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक सपाट बेंच पर अपनी पीठ सीधी करके बैठें और आपके पैर ज़मीन पर सपाट हों।","समर्थन के लिए अपने हाथों को बेंच के किनारों पर रखें।","अपने पैरों को सीधा रखते हुए धीरे-धीरे उन्हें अपने सामने ऊपर उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0690', 'Seated Lower Back Stretch', 'back', 'lats', '["glutes","hamstrings"]', 'body weight', 'strength', NULL, '["Sit on the edge of a chair with your feet flat on the ground.","Place your hands on your thighs or on the sides of the chair for support.","Slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your lower back and hold for 20-30 seconds.","Slowly return to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके कुर्सी के किनारे पर बैठें।","समर्थन के लिए अपने हाथों को अपनी जांघों पर या कुर्सी के किनारों पर रखें।","अपनी पीठ को सीधा रखते हुए धीरे-धीरे अपने कूल्हों से आगे की ओर झुकें।","अपनी पीठ के निचले हिस्से में खिंचाव महसूस करें और 20-30 सेकंड तक रुकें।","धीरे-धीरे प्रारंभिक स्थिति में लौटें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2567', 'Seated Piriformis Stretch', 'upper legs', 'glutes', '["hamstrings"]', 'body weight', 'strength', NULL, '["Sit on the ground with your legs extended in front of you.","Bend your right knee and place your right foot on the outside of your left knee.","Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["अपने पैरों को सामने फैलाकर जमीन पर बैठें।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने पैर को अपने बाएं घुटने के बाहर रखें।","अपनी बाईं कोहनी को अपने दाहिने घुटने के बाहर रखें और धीरे से अपने धड़ को दाईं ओर मोड़ें।","20-30 सेकंड के लिए खिंचाव बनाए रखें, फिर किनारे बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0691', 'Seated Side Crunch (Wall)', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', NULL, '["Sit on the floor with your back against a wall and your legs extended in front of you.","Bend your knees and place your feet flat on the floor, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lean to one side, bringing your elbow towards your hip.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["दीवार के सहारे अपनी पीठ टिकाकर फर्श पर बैठें और आपके पैर आपके सामने फैले हुए हों।","अपने घुटनों को मोड़ें और अपने पैरों को फर्श पर, कूल्हे की चौड़ाई के बराबर दूरी पर रखें।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को संलग्न करें और एक तरफ झुकें, अपनी कोहनी को अपने कूल्हे की ओर लाएं।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1587', 'Seated Wide Angle Pose Sequence', 'upper legs', 'hamstrings', '["quadriceps","calves"]', 'body weight', 'strength', NULL, '["Sit on the ground with your legs extended in a wide angle.","Flex your feet and engage your quadriceps.","Place your hands on the ground behind you for support.","Keeping your back straight, lean forward from your hips.","Continue leaning forward until you feel a stretch in your hamstrings.","Hold this position for a few breaths.","Slowly release the stretch and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को चौड़े कोण में फैलाकर जमीन पर बैठें।","अपने पैरों को मोड़ें और अपने क्वाड्रिसेप्स को संलग्न करें।","समर्थन के लिए अपने हाथों को अपने पीछे ज़मीन पर रखें।","अपनी पीठ सीधी रखते हुए अपने कूल्हों से आगे की ओर झुकें।","जब तक आप अपनी हैमस्ट्रिंग में खिंचाव महसूस न करें तब तक आगे की ओर झुकते रहें।","कुछ सांसों के लिए इस स्थिति में रहें।","धीरे-धीरे खिंचाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0697', 'Self Assisted Inverse Leg Curl', 'upper legs', 'hamstrings', '["glutes","calves"]', 'body weight', 'strength', NULL, '["Lie flat on your back on a mat or bench with your legs extended.","Place your hands by your sides or under your glutes for support.","Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["किसी चटाई या बेंच पर अपने पैरों को फैलाकर पीठ के बल लेट जाएं।","समर्थन के लिए अपने हाथों को अपने बगल में या अपने ग्लूट्स के नीचे रखें।","अपने घुटनों को मोड़ें और अपने पैरों को ज़मीन से ऊपर उठाएं, अपनी जांघों को अपनी छाती की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1766', 'Self Assisted Inverse Leg Curl', 'upper legs', 'hamstrings', '["glutes","calves"]', 'body weight', 'strength', NULL, '["Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Place your hands on the side handles of the machine for support.","Keeping your upper body stationary, exhale and curl your legs upward as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Slowly lower your legs back to the starting position while inhaling.","Repeat for the desired number of repetitions."]', '["लेग कर्ल मशीन पर अपने पैरों को फैलाकर और अपनी एड़ियों को गद्देदार लीवर के नीचे झुकाकर लेटें।","समर्थन के लिए अपने हाथों को मशीन के साइड हैंडल पर रखें।","अपने ऊपरी शरीर को स्थिर रखते हुए सांस छोड़ें और जहां तक ​​संभव हो अपने पैरों को ऊपर की ओर मोड़ें।","जब आप अपनी हैमस्ट्रिंग को निचोड़ें तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","सांस लेते हुए धीरे-धीरे अपने पैरों को वापस शुरुआती स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0696', 'Self Assisted Inverse Leg Curl (On Floor)', 'upper legs', 'hamstrings', '["glutes","calves"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and place your feet flat on the ground, hip-width apart.","Lift your hips off the ground, engaging your glutes and hamstrings.","Slowly curl your legs towards your glutes, keeping your hips lifted.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Lower your hips back down to the ground.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","अपने घुटनों को मोड़ें और अपने पैरों को ज़मीन पर सपाट रखें, कूल्हे की चौड़ाई से अलग।","अपने कूल्हों को ज़मीन से ऊपर उठाएं, अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","अपने कूल्हों को ऊपर उठाते हुए धीरे-धीरे अपने पैरों को अपने ग्लूट्स की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में लाएँ।","अपने कूल्हों को वापस ज़मीन पर टिकाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3222', 'Semi Squat Jump (Male)', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively, extending your hips and knees while swinging your arms for momentum.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","गति के लिए अपनी भुजाओं को घुमाते हुए, अपने कूल्हों और घुटनों को फैलाते हुए विस्फोटक तरीके से कूदें।","अपने पैरों की उंगलियों पर धीरे से उतरें और तुरंत अगली पुनरावृत्ति पर जाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-3656', 'Short Stride Run', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Find an open space or a treadmill to perform the exercise.","Stand tall with your feet hip-width apart.","Start jogging in place, lifting your knees high and pumping your arms.","After a few seconds, start taking short strides forward, maintaining a quick pace.","Continue running with short strides for the desired duration or distance."]', '["व्यायाम करने के लिए एक खुली जगह या ट्रेडमिल ढूंढें।","अपने पैरों को कूल्हे-चौड़ाई से अलग करके सीधे खड़े रहें।","अपने घुटनों को ऊंचा उठाते हुए और अपनी बाहों को पंप करते हुए, अपनी जगह पर जॉगिंग करना शुरू करें।","कुछ सेकंड के बाद, तेज गति बनाए रखते हुए छोटे-छोटे कदम आगे बढ़ाना शुरू करें।","वांछित अवधि या दूरी तक छोटे-छोटे कदमों के साथ दौड़ना जारी रखें।"]', NULL, 9.8, 'time', 0, 'opengym', 1),
('og-1763', 'Shoulder Grip Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Hang freely with your arms fully extended.","Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["पुल-अप बार को कंधे की चौड़ाई की पकड़ से पकड़ें, हथेलियाँ आपसे दूर की ओर हों।","अपनी भुजाओं को पूरी तरह फैलाकर स्वतंत्र रूप से लटकें।","अपनी पीठ की मांसपेशियों को संलग्न करें और अपने शरीर को बार की ओर तब तक खींचें जब तक कि आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3699', 'Shoulder Tap', 'waist', 'abs', '["shoulders","triceps"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Continue alternating shoulder taps while keeping your hips and torso stable.","Repeat for the desired number of repetitions."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपने दाहिने हाथ को जमीन से ऊपर उठाएं, अपने बाएं कंधे पर टैप करें।","अपने दाहिने हाथ को वापस ज़मीन पर रखें और अपने बाएँ हाथ से अपने दाहिने कंधे को थपथपाते हुए इसे दोहराएँ।","अपने कूल्हों और धड़ को स्थिर रखते हुए कंधे को बारी-बारी से थपथपाते रहें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0699', 'Shoulder Tap Push-Up', 'chest', 'pectorals', '["triceps","core"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you push back up, lift your right hand off the ground and tap your left shoulder.","Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Continue alternating shoulder taps with each push-up repetition.","Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा करके और अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","जैसे ही आप पीछे की ओर धकेलते हैं, अपना दाहिना हाथ ज़मीन से उठाएँ और अपने बाएँ कंधे को थपथपाएँ।","अपने दाहिने हाथ को ज़मीन पर लौटाएँ और पुश-अप दोहराएँ, इस बार अपने बाएँ हाथ को उठाएँ और अपने दाहिने कंधे को थपथपाएँ।","प्रत्येक पुश-अप दोहराव के साथ कंधे को बारी-बारी से थपथपाते रहें।","एक स्थिर कोर बनाए रखें और पूरे अभ्यास के दौरान अत्यधिक कूल्हे घुमाने से बचें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1774', 'Side Bridge Hip Abduction', 'upper legs', 'abductors', '["glutes","obliques"]', 'body weight', 'strength', NULL, '["Lie on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Pause for a moment at the top, then lower your leg back down.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को फैलाकर और एक दूसरे के ऊपर रखकर अपनी तरफ लेटें।","अपनी कोहनी को सीधे अपने कंधे के नीचे रखते हुए, अपने आप को अपनी बांह के बल ऊपर उठाएं।","अपने कोर को संलग्न करें और अपने कूल्हों को जमीन से ऊपर उठाएं, जिससे आपके सिर से आपके पैरों तक एक सीधी रेखा बन जाए।","अपने कोर को व्यस्त रखते हुए, अपने कूल्हों को घुमाए बिना अपने ऊपरी पैर को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर अपना पैर वापस नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0705', 'Side Bridge v. 2', 'waist', 'abs', '["obliques","glutes"]', 'body weight', 'strength', NULL, '["Lie on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the starting position.","Repeat on the other side."]', '["अपने पैरों को फैलाकर और एक दूसरे के ऊपर रखकर अपनी तरफ लेटें।","अपनी कोहनी को 90 डिग्री के कोण पर मोड़ते हुए अपने अग्रबाहु को सीधे अपने कंधे के नीचे जमीन पर रखें।","अपने कोर को संलग्न करें और अपने कूल्हों को जमीन से ऊपर उठाएं, जिससे आपके सिर से आपके पैरों तक एक सीधी रेखा बन जाए।","वांछित समय तक इस स्थिति में रहें।","अपने कूल्हों को वापस प्रारंभिक स्थिति में लाएँ।","दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0709', 'Side Hip (On Parallel Bars)', 'waist', 'abs', '["obliques","hip flexors"]', 'body weight', 'strength', NULL, '["Stand between two parallel bars with your feet shoulder-width apart.","Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Engage your abs and slowly lift your legs to the side, keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए दो समानांतर पट्टियों के बीच खड़े हो जाएं।","अपने हाथों को सलाखों पर रखें और अपने वजन को अपनी भुजाओं पर सहारा देते हुए अपने शरीर को जमीन से ऊपर उठाएं।","अपने पेट को संलग्न करें और धीरे-धीरे अपने पैरों को सीधा रखते हुए बगल की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0710', 'Side Hip Abduction', 'upper legs', 'abductors', '["glutes","quadriceps"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your hands on your hips.","Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर और अपने हाथों को अपने कूल्हों पर रखकर खड़े हो जाएं।","अपना वजन एक पैर पर डालें और दूसरे पैर को सीधा रखते हुए बगल की तरफ उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैर को वापस प्रारंभिक स्थिति में ले आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1358', 'Side Lying Floor Stretch', 'back', 'lats', '["obliques","glutes"]', 'body weight', 'strength', NULL, '["Lie on your side with your legs straight and your bottom arm extended straight overhead.","Bend your top knee and place your foot on the ground in front of your bottom leg.","Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.","Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.","Hold the stretch for 20-30 seconds, then slowly lower your leg back down.","Repeat on the other side."]', '["अपने पैरों को सीधा करके अपनी तरफ लेटें और आपकी निचली भुजा सीधे ऊपर की ओर फैली हुई हो।","अपने ऊपरी घुटने को मोड़ें और अपने पैर को अपने निचले पैर के सामने ज़मीन पर रखें।","अपने ऊपरी हाथ को अपने सिर के ऊपर ले जाएं और किसी स्थिर चीज़ को पकड़ें, जैसे दीवार या फर्नीचर का टुकड़ा।","धीरे-धीरे अपने निचले पैर को जमीन से ऊपर उठाएं, इसे सीधा रखें, जब तक कि आप अपनी तरफ खिंचाव महसूस न करें।","20-30 सेकंड तक खिंचाव बनाए रखें, फिर धीरे-धीरे अपने पैर को वापस नीचे लाएँ।","दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3667', 'Side Lying Hip Adduction (Male)', 'upper legs', 'adductors', '["glutes","hamstrings"]', 'body weight', 'strength', NULL, '["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को सीधा और एक दूसरे के ऊपर रखकर करवट से लेटें।","समर्थन के लिए अपनी निचली भुजा को अपने सिर के नीचे रखें।","अपने एडक्टर्स को संलग्न करें और अपने कूल्हों को घुमाए बिना या पीछे की ओर झुके बिना अपने ऊपरी पैर को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1775', 'Side Plank Hip Adduction', 'upper legs', 'adductors', '["obliques","glutes"]', 'body weight', 'strength', NULL, '["Start by lying on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को फैलाकर और एक दूसरे के ऊपर रखकर अपनी तरफ लेटकर शुरुआत करें।","अपनी कोहनी को सीधे अपने कंधे के नीचे रखते हुए, अपने आप को अपनी बांह के बल ऊपर उठाएं।","अपने कोर को संलग्न करें और अपने कूल्हों को जमीन से ऊपर उठाएं, जिससे आपके सिर से आपके पैरों तक एक सीधी रेखा बन जाए।","साइड प्लैंक की स्थिति बनाए रखते हुए, अपने ऊपरी पैर को सीधा रखते हुए छत की ओर उठाएं।","धीरे-धीरे अपने पैर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0716', 'Side Push Neck Stretch', 'neck', 'levator scapulae', '["trapezius","sternocleidomastoid"]', 'body weight', 'strength', NULL, '["Stand or sit up straight with your shoulders relaxed.","Tilt your head to the right, bringing your right ear towards your right shoulder.","Place your right hand on the left side of your head and gently apply pressure to increase the stretch.","Hold the stretch for 15-30 seconds.","Repeat on the other side, tilting your head to the left and applying pressure with your left hand.","Repeat the stretch 2-3 times on each side."]', '["अपने कंधों को आराम देते हुए सीधे खड़े हों या बैठें।","अपने सिर को दाईं ओर झुकाएं, अपने दाहिने कान को अपने दाहिने कंधे की ओर लाएं।","अपने दाहिने हाथ को अपने सिर के बाईं ओर रखें और खिंचाव बढ़ाने के लिए धीरे से दबाव डालें।","15-30 सेकंड तक खिंचाव बनाए रखें।","दूसरी तरफ दोहराएं, अपने सिर को बाईं ओर झुकाएं और अपने बाएं हाथ से दबाव डालें।","प्रत्येक तरफ 2-3 बार खिंचाव दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0717', 'Side Push-Up', 'upper arms', 'triceps', '["shoulders","chest","core"]', 'body weight', 'strength', NULL, '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को फैलाकर और एक दूसरे के ऊपर रखकर अपनी तरफ लेटकर शुरुआत करें।","अपने निचले हाथ को सीधे अपने कंधे के नीचे जमीन पर रखें, उंगलियां आगे की ओर हों।","अपने शरीर को जमीन से ऊपर उठाने के लिए अपने निचले हाथ से दबाएं, अपने पैरों को सीधा रखें और अपने कोर को व्यस्त रखें।","अपने ऊपरी हाथ को सीधे छत की ओर फैलाएं, जिससे आपके सिर से आपकी एड़ी तक एक सीधी रेखा बन जाए।","नियंत्रण के साथ अपने शरीर को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0721', 'Side Wrist Pull Stretch', 'lower arms', 'forearms', '["wrists","hands"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your arms extended in front of you.","Extend your right arm out to the side, parallel to the ground, with your palm facing down.","With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपकी भुजाएं आपके सामने फैली हुई हों।","अपनी दाहिनी भुजा को जमीन के समानांतर बगल की ओर फैलाएं, जिसमें आपकी हथेली नीचे की ओर हो।","अपने बाएं हाथ से, अपने दाहिने हाथ को पकड़ें और धीरे से इसे अपने शरीर की ओर खींचें, अपने दाहिने अग्रबाहु में खिंचाव महसूस करें।","15-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0720', 'Side-To-Side Chin', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body relaxed.","Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Once your chin is above the bar, lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","पुल-अप बार को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को शिथिल करके बार से लटकें।","अपने शरीर को सीधा रखते हुए, अपनी कोहनियों को मोड़कर और अपनी ठुड्डी को बार की ओर लाकर अपने आप को ऊपर खींचें।","एक बार जब आपकी ठुड्डी बार के ऊपर आ जाए, तो अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3213', 'Side-To-Side Toe Touch (Male)', 'waist', 'abs', '["obliques","hip flexors"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Repeat the side-to-side bending motion for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी भुजाएं बगल तक फैला लें।","कमर को दाहिनी ओर झुकाएं, अपने दाहिने हाथ को अपने दाहिने पैर की ओर ले जाएं, जबकि अपने बाएं हाथ को बगल की ओर फैलाए रखें।","प्रारंभिक स्थिति में लौटें और फिर कमर को बाईं ओर झुकाएं, अपने बाएं हाथ को अपने बाएं पैर की ओर ले जाएं, जबकि अपने दाहिने हाथ को बगल की ओर फैलाए रखें।","पुनरावृत्ति की वांछित संख्या के लिए अगल-बगल झुकने की गति को दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0725', 'Single Arm Push-Up', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'body weight', 'strength', 'intermediate', '["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.","Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.","Repeat the movement, alternating the arm you extend with each repetition."]', '["अपने हाथों को कंधे की चौड़ाई पर फैलाकर और एक हाथ को दूसरे की तुलना में थोड़ा चौड़ा करके पुश-अप स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा रखते हुए अपने शरीर को जमीन की ओर नीचे करें।","जैसे ही आप अपने आप को नीचे करते हैं, अपना वजन एक तरफ ले जाएं और विपरीत हाथ को जमीन से ऊपर उठाएं, इसे सीधे बगल की तरफ फैलाएं।","अपने शरीर को वापस प्रारंभिक स्थिति में उठाने के लिए अपनी छाती और ट्राइसेप्स पर दबाव डालें, साथ ही अपनी विस्तारित भुजा को वापस जमीन पर लाएँ।","प्रत्येक दोहराव के साथ अपने हाथ को बारी-बारी से बढ़ाते हुए, इस क्रिया को दोहराएं।"]', '["Single-Arm_Push-Up/0.jpg","Single-Arm_Push-Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3645', 'Single Leg Bridge With Outstretched Leg', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'body weight', 'strength', NULL, '["Lie on your back with your knees bent and feet flat on the ground.","Extend one leg straight out in front of you.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेटें।","एक पैर को अपने सामने सीधा फैलाएं।","अपने ग्लूट्स को संलग्न करें और अपने कूल्हों को ज़मीन से ऊपर उठाएं, जिससे आपके घुटनों से लेकर आपके कंधों तक एक सीधी रेखा बन जाए।","एक क्षण के लिए शीर्ष पर रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0727', 'Single Leg Calf Raise (On A Dumbbell)', 'lower legs', 'calves', '["ankles","feet"]', 'dumbbell', 'strength', NULL, '["Stand with your feet hip-width apart and hold a dumbbell in one hand.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch to the other leg."]', '["अपने पैरों को कूल्हे-चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में डंबल पकड़ लें।","एक पैर को जमीन से ऊपर उठाएं और दूसरे पैर पर संतुलन बनाएं।","अपनी पिंडली की मांसपेशियों का उपयोग करते हुए धीरे-धीरे अपनी एड़ी को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ, फिर दूसरे चरण पर जाएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0730', 'Single Leg Platform Slide', 'upper legs', 'hamstrings', '["glutes","quadriceps"]', 'body weight', 'strength', NULL, '["Start by standing with one foot on a platform or slide board.","Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Keep your core engaged and maintain a straight posture throughout the movement.","Slowly return to the starting position by sliding your foot back to the initial position.","Repeat the movement for the desired number of repetitions, then switch legs."]', '["किसी प्लेटफॉर्म या स्लाइड बोर्ड पर एक पैर रखकर खड़े होकर शुरुआत करें।","अपने घुटने को थोड़ा मोड़ें और अपने पैर को फैलाते हुए पैर को प्लेटफॉर्म पर पीछे की ओर सरकाएं।","अपने कोर को व्यस्त रखें और पूरे आंदोलन के दौरान सीधी मुद्रा बनाए रखें।","अपने पैर को प्रारंभिक स्थिति में वापस सरकाते हुए धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","वांछित संख्या में दोहराव के लिए आंदोलन को दोहराएं, फिर पैर बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1759', 'Single Leg Squat (Pistol) Male', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and arms extended in front of you.","Lift your right foot off the ground and extend it forward.","Slowly lower your body down by bending your left knee and pushing your hips back.","Keep your chest up and your back straight as you lower yourself down.","Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और भुजाएं आपके सामने फैली हुई हों।","अपने दाहिने पैर को जमीन से ऊपर उठाएं और आगे की ओर फैलाएं।","अपने बाएं घुटने को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए धीरे-धीरे अपने शरीर को नीचे लाएं।","नीचे उतरते समय अपनी छाती ऊपर और पीठ सीधी रखें।","तब तक नीचे जाएँ जब तक आपकी बायीं जांघ ज़मीन के समानांतर न हो जाए, या जितना नीचे आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी बायीं एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1489', 'Sissy Squat', 'upper legs', 'quads', '["calves","glutes"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold onto a stable object for balance if needed.","Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके पैर की उंगलियां थोड़ी बाहर की ओर हों।","यदि आवश्यक हो तो संतुलन के लिए किसी स्थिर वस्तु को पकड़ें।","अपने घुटनों को मोड़कर और अपने धड़ को सीधा रखते हुए पीछे झुकते हुए धीरे-धीरे अपने शरीर को नीचे लाएँ।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें जमीन के समानांतर न हो जाएं या जहां तक ​​आप आराम से जा सकें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
